programs.haiku:
"""Line-length detector: a newline's activation depends on how long the line before it is.

The component is a line-break feature. Measured by the UTF-8 bytes of text since the
previous newline (in the document), at a line break it is:
  - about 0 for short lines (under ~70 bytes, about 60 English characters);
  - positive, about +0.5, for lines of roughly 80 to 170 bytes (a full, wrapped-looking
    line of English prose or code), peaking near 90 to 150 bytes;
  - fading to 0 around 200 to 230 bytes and negative beyond that: -0.5 at 300 bytes and
    about -1 for lines of 700 bytes or more (very long lines, or lines of non-Latin text
    that use several bytes per character).
Every token that is not a newline predicts 0.

Main program: `carry` holds the byte count of the current line and the document id; at a
newline token the program returns the curve value for that count and resets the count;
otherwise it adds the token's bytes to the count and returns 0.
"""

READS = ()

# (line length in UTF-8 bytes, mean activation at a line break) knots, linear in between.
LENGTHS = [0, 40, 60, 80, 90, 150, 170, 200, 230, 260, 300, 400, 700, 100000]
VALUES = [0.0, -0.1, 0.0, 0.36, 0.57, 0.5, 0.4, 0.1, -0.02, -0.2, -0.55, -0.76, -1.1, -1.1]


def curve(n):
    for i in range(1, len(LENGTHS)):
        if n <= LENGTHS[i]:
            x0, x1 = LENGTHS[i - 1], LENGTHS[i]
            y0, y1 = VALUES[i - 1], VALUES[i]
            return y0 + (y1 - y0) * (n - x0) / (x1 - x0)
    return VALUES[-1]


def token_bytes(token):
    # A token that is part of a split multi-byte character decodes alone to U+FFFD,
    # which stands for one byte of it.
    return 1 if token == "�" else len(token.encode("utf-8"))


def step(carry, prefix, upstream):
    # carry: (bytes since the last newline, document id of the previous token)
    length, doc = carry if carry is not None else (0, None)
    if prefix.document_ids[-1] != doc:
        length = 0  # a new document starts a new line count
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if "\n" in token or "\r" in token:
        return (0, doc), float(curve(length))
    return (length + token_bytes(token), doc), 0.0

programs.sol:
"""Recognize Chinese 离/離 ('leave/away') and 距/距离 ('distance').

Compounds are weaker than a lone character. Preceding compound partners
(e.g. 分離, separation, or 游離, dissociation) also weaken the response.
Recent kana is a cue to reduce the response for Japanese usage. UTF-8 fragments are handled explicitly: a split 离 can fire
both before and when its last byte arrives.

Small additional rules cover an opening backslash, the numeric prefix 12,
and the 'ug' part of centrifugation. Otherwise predict zero, leaving the
component's many weak and less interpretable responses unexplained.
"""

import regex

READS = ()
KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, beginning, tail = 0, '', b''
    else:
        _, position, beginning, tail = carry
    before = tail.decode('utf-8', errors='replace')
    japanese = bool(KANA.search(before))
    word = token.replace('離', '离')
    value = 0.0

    if word == '离':
        value = 8.0 if japanese else 11.0
        # These partners form a compound across the token boundary.
        if before.endswith(('游', '剥', '剝')):
            value = 4.8
        elif before.endswith('分'):
            value = 2.0
        elif before.endswith(('远', '遠', '逃')):
            value = 6.0
    elif word == '距':
        value = 2.5 if before.endswith(('相', '轴', '軸')) else 5.8
    elif word in ('距离', '的距离'):
        value = 1.7 if japanese else (3.5 if word == '的距离' else 5.8)
        if before.endswith(('近', '长', '長', '短')):
            value = 1.8
    elif word in ('离开', '离开了', '脱离', '远离', '离不开'):
        value = 3.5
    elif word in ('近距离', '零距离', '撤离', '隔离'):
        value = 1.4
    elif '离' in word and len(word) <= 3:
        value = 0.6 if word == '离子' else 2.2
    elif word in ('临', '臨'):  # approach / be close to
        value = 1.2

    joined = tail + raw
    if raw == b'\xa6' and tail.endswith(b'\xe7'):
        # The incomplete character prefix shared by 离 and 福, among others.
        value = 7.2
    elif raw == b'\xbb' and joined.endswith('离'.encode()):
        value = 14.7
    elif raw == b'\xa2' and joined.endswith('離'.encode()):
        value = 12.5

    if position == 0 and token.endswith('\\') and '"' not in token:
        value = 1.6 / token.count('\\')
    elif position == 0 and token == '\\n':
        value = 1.2
    elif token == '2' and beginning in ('1', '12'):
        value = 2.62 if beginning == '1' else 1.26
    elif token == 'ug' and before.lower().endswith('centrif'):
        value = 0.68

    beginning = beginning + token if position < 3 else ''
    return (doc, position + 1, beginning, joined[-96:]), value

"""Approximate lexical continuation across token boundaries.

Short neighboring pieces get positive values when they form a familiar
Chinese, Japanese or Korean word. Dictionaries and corpus frequency set
coarse amplitudes. Completing a character from UTF-8 fragments gets a
stronger response. Small defaults cover adjacent Han text, kana and Thai;
most other text is zero. Document changes reset the byte-decoding state.
These rules omit the exact strengths of individual word pairs.
"""
import codecs
import math
from functools import lru_cache
import regex
import cedict
import jmdict
import opencc
from wordfreq import get_frequency_dict

READS = ()
_FREQUENCIES = {lang: get_frequency_dict(lang) for lang in ('zh', 'ja', 'ko')}
_SIMPLIFY = opencc.OpenCC('t2s')
_HAN = regex.compile(r'\p{Script=Han}')
_KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')
_KOREAN = regex.compile(r'\p{Script=Hangul}')
_THAI = regex.compile(r'\p{Script=Thai}')


@lru_cache(maxsize=32768)
def frequency(word):
    """Largest Chinese/Japanese/Korean log frequency, on the Zipf scale."""
    simple = _SIMPLIFY.convert(word)
    f = max(_FREQUENCIES['zh'].get(simple, 0),
            _FREQUENCIES['ja'].get(word, 0),
            _FREQUENCIES['ko'].get(word, 0))
    return 9 + math.log10(f) if f else 0.0


@lru_cache(maxsize=32768)
def is_word(text):
    return bool(cedict.glosses(text) or jmdict.glosses(text))


@lru_cache(maxsize=32768)
def decode_fragment(data):
    decoder = codecs.getincrementaldecoder('utf-8')('replace')
    text = decoder.decode(data)
    return text, decoder.getstate()[0]


@lru_cache(maxsize=65536)
def response(previous, current, assembled, incomplete):
    p = (previous or b'').decode('utf-8', 'replace').strip()
    s = current.decode('utf-8', 'replace').strip()
    joint = ((previous or b'') + current).decode('utf-8', 'replace').strip()
    han = bool(_HAN.fullmatch(s[-1:]))
    prior_han = bool(_HAN.fullmatch(p[-1:]))
    kana = bool(_KANA.fullmatch(s[-1:]))
    korean = bool(_KOREAN.fullmatch(s[-1:]))
    if incomplete > 1:
        return 0.60 if prior_han and len(joint) <= 2 else 0.04
    if not (han or kana or korean or assembled):
        return 0.075 if _THAI.fullmatch(s[-1:]) else 0.0
    if kana:
        return -0.04
    f = frequency(joint)
    if assembled:
        if p and f > 1.2:
            return 1.5
        return 0.55 if prior_han else 0.08
    if p and f > 1.2:
        if len(joint) > 2:
            return 0.085
        if f > 3.75:
            return 0.65 if frequency(s) < 6.1 else 0.43
        return 0.52 if is_word(joint) else 0.24
    if p and cedict.glosses(p[-1:] + s):
        return 0.26
    if han:
        if len(s) > 1:
            return -0.065
        if prior_han and len(p) == 1 and frequency(p) < 5.9:
            return 0.16 if frequency(s) < 5.5 else 0.03
        return -0.04
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, pending, anchor = None, b'', None
    else:
        _, previous, pending, anchor = carry
    data = prefix.token_bytes[-1]
    assembled = bool(pending)
    current = pending + data if assembled else data
    prior = anchor if assembled else previous
    text, tail = decode_fragment(current)
    value = response(prior, current, assembled, len(tail))
    if tail:
        anchor = text.encode() if text else prior
        previous = text.encode() if text else previous
    else:
        previous, anchor = current, None
    return (doc, previous, tail, anchor), float(value)

"""A coarse local spelling-and-boundary approximation, not a semantic model.

It gives a small positive document-start value, larger for module declarations.
Within text, Korean second-character continuations (especially r/l + eu) are
positive. Japanese kana sounds, preceding kanji, and a few grammatical forms
control smaller values. Cyrillic -at after a one-character prefix is negative;
repeated middle dots are positive. It joins split UTF-8 characters and resets
state at document boundaries.
Many lexical and contextual differences remain unmodeled.
"""
import codecs
import unicodedata as ud
from functools import lru_cache

READS: tuple[str, ...] = ()
QUESTIONS = {'どこ', 'どれ', 'どちら', 'どんな'}

@lru_cache(maxsize=256)
def kana(ch):
    """Unicode kana spelling: consonant row and final vowel."""
    name = ud.name(ch, '')
    if not name.startswith('HIRAGANA'):
        return '', ''
    sound = name.split()[-1]
    return ('vowel' if sound in {'A', 'I', 'U', 'E', 'O'}
            else sound[0], sound[-1])


def japanese(s, previous, partial):
    row, vowel = kana(s[0])
    if s in QUESTIONS:
        return -1.61
    if vowel == 'O':
        if row == 'W':
            return -0.20
        return -0.36 if s in {'こう', 'そう', 'ああ', 'どう'} else -0.02
    if row == 'R':
        return 0.38 if len(s) == 1 else 0.13
    if ud.name(previous, '').startswith('CJK'):
        if row == 'vowel':
            return 0.74 if len(s) == 1 else 0.18
        if row == 'K':
            return 0.34 if len(s) == 1 else 0.08
        if s.endswith('て'):
            return -0.11
        if row == 'N' and vowel == 'N':  # the moraic nasal, not the n-row
            return 0.51
        return {'M': 0.35, 'T': 0.31, 'B': 0.49,
                'H': -0.09, 'S': 0.13, 'W': 0.37}.get(row, 0.02)
    if s == 'たい':
        return -0.63
    if kana(previous)[1] == 'A':
        return 0.12
    if s.endswith('る'):
        return 0.17
    return 0.42 if partial else 0.01


@lru_cache(maxsize=4096)
def sounds(ch):
    """Hangul onset, vowel and optional final consonant, as Unicode jamo."""
    if not ud.name(ch, '').startswith('HANGUL SYLLABLE'):
        return ('-', '-', '-')
    j = ud.normalize('NFD', ch)
    return j[0], j[1], j[2] if len(j) == 3 else '-'


def korean(text, previous, word_length, partial):
    if text[0].isspace():
        return 0.0
    onset, vowel, coda = sounds(text[0])
    # Strongest at the second written character of a word, particularly r/l.
    if word_length == 1:
        if onset == 'ᄅ':
            if vowel == 'ᅳ':  # rieul + eu
                return 4.0
            return 2.13 if sounds(previous)[1] == 'ᅡ' else 0.83
        return 1.03 if onset == 'ᄂ' else 0.30  # nieun: n
    if partial:
        return 3.53 if coda == 'ᆮ' else 0.36  # final d/t
    return 0.075


def document_start(s):
    if not s:
        return 0.20
    if s in {'import', 'using', 'package'}:  # module/namespace declarations
        return 1.10
    if s.startswith('<|'):
        return 0.06
    if not s[0].isascii():
        return 0.25
    if s.isalpha():
        return 0.09 if s.isupper() else 0.12 if s.istitle() else 0.21
    return 0.04 if s.isdecimal() else 0.07


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, b'', '', 0)
    _, pending, tail, word_length = carry
    partial = bool(pending)
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'replace', False)
    pending = raw[used:]
    previous = tail[-1:] or ' '
    s = text.strip()
    value = document_start(s) if first else 0.0
    if s and not first:
        name = ud.name(s[0], '')
        if name.startswith('HANGUL'):
            value = korean(text, previous, word_length, partial)
        elif name.startswith('HIRAGANA'):
            value = japanese(s, previous, partial)
        elif (s == 'ат' and word_length == 1
              and ud.name(previous, '').startswith('CYRILLIC')):
            value = -1.0  # Cyrillic -at following a one-character prefix
    if len(s) >= 2 and set(s) == {'·'}:
        value = 1.95
    if any(c.isspace() for c in text):
        word_length = (len(text.split()[-1])
                       if text and not text[-1].isspace() else 0)
    else:
        word_length += len(text)
    return (doc, pending, (tail + text)[-1:], word_length), value

"""A spelling-fragment detector, strongest for e followed by v.

It recognizes Latin ev/ew and Cyrillic ев, including an e at the end
of the previous token. Short fragments get larger negative responses;
spaces, capitalization and familiar English words usually weaken them.
There is a little negative spillover onto a following word fragment,
and a separate positive response to the end-of-text marker.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def spelling(s):
    allowed = all(ord(c) < 128 or any(
        script in unicodedata.name(c, '')
        for script in ('LATIN', 'CYRILLIC')) for c in s)
    return anyascii(s).lower() if allowed else ''


@lru_cache(maxsize=8192)
def frequency(s):
    return zipf_frequency(s.strip(), 'en')


def fragment(s, previous):
    t, prev = spelling(s), spelling(previous)
    n, pn = len(t.strip()), len(prev)
    adjacent = bool(t and t[0].isalpha())
    if adjacent and prev.endswith('e') and t.startswith(('v', 'w')):
        # Electronvolt symbols, split just before their final V.
        if s == 'V' and previous.strip() in ('Ge', 'Me', 'Te', 'ke'):
            unit = previous.strip()
            return -10.5 if unit == 'Ge' else -5.8 if unit == 'ke' else -8.2
        if n == 1:
            if t == 'w':
                return -0.6
            return -5.8 if pn <= 3 else -2.4
        if n == 2:
            return -3.0 if frequency(s) < 3.3 else -1.5
        if n == 3:
            return -0.6 if t[1:2] == 'e' else -1.45
        return -0.43 if frequency(s) < 3.9 else 0.0

    match = re.search('e[vw]', t)
    if not match:
        return 0.0
    space = s.startswith(' ')
    cyrillic = any('CYRILLIC' in unicodedata.name(c, '') for c in s)
    if n <= 2:
        if t[match.end()-1] == 'w':
            return -0.6
        if space:
            return -2.7
        if not cyrillic and s.istitle():
            return -2.3
        return -4.5 if pn == 2 else -5.8
    if cyrillic:
        return -4.9 if n == 3 else -1.5
    if frequency(s) > 4.2:
        return -0.08
    if t.endswith('ev'):
        strength = (3.5 if frequency(s) < 3.5 else 1.6) if n == 3 else 1.0
    elif t[match.end()-1] == 'w':
        return -3.6 if t.strip() == 'iew' else -0.08
    else:
        strength = 2.4 if n == 3 else 1.1 if n == 4 else 0.25
    return -strength * (0.7 if space else 1.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, last = ('', 0.0) if carry is None or carry[0] != doc else carry[1:]
    s = prefix.token_strings[-1]
    base = 1.05 if s == '<|endoftext|>' else fragment(s, previous)
    value = base
    if abs(base) < 1 and last < -1 and s and s[0].isalpha():
        value += 0.2 * last
    return (doc, s, base), float(value)

"""A sparse, multilingual coordination signal, not a general syntax parser.

Conjunction spellings and list separators usually receive positive values.
Recent word-frequency evidence disambiguates short Latin-script conjunctions.
An ampersand joining phrases is positive; a C++ reference or programming use
is negative. There is also a negative response to internal -en/-enn syllables
in West Slavic text. Everything else is approximated by zero.
"""
import re
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = 'en es pt it fr de cs sk pl sh nl id fi sv da nb tr ro hu'.split()

# Written coordinating conjunctions: and, or, and related list linkers.
CONJUNCTIONS = {
    'и': 1.2, 'И': 0.7, 'или': 1.35, 'і': 1.5,
    'und': 0.4, 'oder': 0.5, 'sowie': 1.3,
    'oraz': 2.2, 'czy': 1.5, 'lub': 0.4,
    'ou': 0.5, 've': 0.2, 'og': 0.9, 'och': 0.55,
    'ja': 0.8, 'și': 1.5, 'şi': 1.5,
}
EAST_ASIAN = {
    '与': 1.0, '與': 1.4, '和': 0.7, '及': 2.2, '兼': 4.0,
    '或': 1.15, '或者': 0.6, '或是': 0.8, '以及': 0.4,
    'と': 0.2, 'や': 0.3, 'および': 2.7, '及び': 2.7,
    '및': 2.2, '와': 0.95, '과': 0.3,
    '・': 0.9, '··': 0.65, '＆': 3.0,
}
# Ambiguous spellings require evidence of the appropriate language.
CONTEXTUAL = {
    'a': {'cs': 3.6, 'sk': 3.6, 'pl': 1.0},
    'i': {'cs': 3.2, 'sk': 3.2, 'pl': 2.45},
    'e': {'it': 1.1, 'pt': 1.1, 'es': 2.8},
    'ed': {'it': 5.0}, 'y': {'es': 1.0},
    'o': {'es': 1.2, 'it': 1.2}, 'u': {'de': 1.2},
    'dan': {'id': 0.3, 'nl': -3.4}, 'si': {'ro': 2.5},
    'et': {'fr': 0.75},
}

@lru_cache(maxsize=30000)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)

def language(text):
    words = re.findall(r'[^\W\d_]+', text.lower())[-18:]
    scores = [0.0] * len(LANGUAGES)
    for word in words:
        if len(word) > 1:
            for i, value in enumerate(frequencies(word)):
                scores[i] += value
    return LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]

def ampersand(token, before):
    if token.count('&') > 1:  # && is a different programming operator.
        return 0.0
    left = token.split('&')[0].strip()
    if left.startswith('>'):
        before += left  # A template-closing bracket may share the token.
    before = before.replace('\\n', '\n').replace('\\t', '\t')
    tail = before.rstrip()
    line = tail.rsplit('\n', 1)[-1]
    quoted = re.search(r'["\']([A-Za-z]+(?: [A-Za-z]+)+)$', line)
    if quoted:  # A quoted prose label, even when surrounded by code.
        before = tail = quoted[1]
    elif re.match(r'\s*(?://|\* |# )', line):
        before = tail = re.sub(r'^\s*(?://|\* |# )', '', line)
    if re.search(r'(?:https?://|www\.)\S*$', tail):
        return -0.3
    if re.search(r'\\(?:begin|frac|hline|dots|vdots|end|text|footnotesize)', before):
        if not tail.endswith('\\'):
            return -0.5  # TeX alignment, not a phrase linker.
    cpp = re.search(
        r'::|#include|\bconst\b|\btemplate\s*<|\b(?:public|private):'
        r'|\b(?:void|int|bool|float|double)\s+\w+\s*\(', before)
    types = r'const|int|bool|float|double|char|size_t|ostream|istream|string|vector'
    type_end = re.search(
        r'(?:\b[A-Z]\w*|\b\w*[A-Z]\w*|\b(?:' + types + r'))$', tail)
    code = re.search(
        r'::|:=|==|=>|assert\w*\(|\bself\.|\.def\(|\bfn\s|#include'
        r'|[a-z_]\w*[A-Z_]\w*\(|\w+\.\w+\(|\b[A-Z]\w*:\s*$', before)
    braces = ('{' in before or '}' in before) and '\\' not in before
    code = code or braces or (before.count(';') >= 2 and
                             re.search(r'=|\w\(|\w\[', before))
    parameter_type = (re.search(r'[(,]\s*(?:const\s+)?\w+$', tail) and
                      re.search(r'\b(?:void|int|double|float|const)\b', before))
    rust = re.search(r'\b(?:fn|impl|let|mut|pub)\b', before)
    if not rust and (parameter_type or
                     (cpp and (type_end or tail.endswith('>')))):
        if not re.search(r'\b(?:export|type)\b', before):
            return -4.7 if token.startswith(' ') else -3.4
    if left.startswith('>') and not cpp:
        return -0.35
    if token.strip() != '&' and not left.startswith('>'):
        return -1.2 if '(' in token else -0.35
    if code or cpp:
        return -1.9
    if re.search(r'[=^$]', before[-70:]):
        return -0.4
    words = re.findall(r'[^\W\d_]+', tail.rstrip('\\ '))
    last = words[-1] if words else ''
    if len(last) <= 1:
        return 1.0
    if tail.endswith(',') or last[0].isupper():
        return 3.7
    if not token[0].isspace() and not tail.endswith('\\'):
        return 0.5
    return 2.5

def predict(token, before):
    word = token.strip()
    if '&' in token:
        return ampersand(token, before)
    if token == 'а' and re.search(r'(?:^|\W)т$', before):
        return 8.0 if re.search('[іїєґІЇЄҐ]', before) else 0.0
    if token == 'i' and re.search(r'(?:^|\W)č$', before):
        return 5.0  # Completion of Czech či, "or".
    if word in EAST_ASIAN:
        if word in {'与', '與', '和', '及'}:
            if regex.search(r'[\p{Hiragana}\p{Katakana}]', before[-100:]):
                return {'与': -3.0, '與': -1.0, '和': -0.85, '及': -1.65}[word]
            if (word in {'与', '與'} and before and
                    before[-1] in '是会會能可将將要已在于於把被的地得'):
                return -0.5
        return EAST_ASIAN[word]
    boundary = token[0].isspace() or not before or not before[-1].isalpha()
    if word in CONJUNCTIONS and boundary:
        return CONJUNCTIONS[word]
    if token.startswith(' ') and word in CONTEXTUAL:
        lang = language(before)
        if word == 'y':
            last = re.findall(r'[^\W\d_]+', before)[-1:]
            if last and last[0][0].isupper():
                if zipf_frequency(last[0], 'es') > zipf_frequency(last[0], 'en') + 0.4:
                    return 1.7
        return CONTEXTUAL[word].get(lang, 1.4 if word == 'et' else 0.0)
    if re.fullmatch(r'[A-Za-z]*enn?', token) and before and before[-1].isalpha():
        if language(before) in {'cs', 'sk', 'pl'}:
            return -2.7
