def arabic_features(token):
    letters = regex.findall(r'\p{Script=Arabic}', token)
    return (sum(c.isalpha() for c in letters),
            any(c in token for c in PERSIAN_FORMS))

READS = ()

MARKUP = {
    '<think>': -1.03,
    '</think>': -2.11,
    '<tool_call>': -0.26,
    '</tool_call>': 0.30,
    '<tool_response>': -0.25,
    '</tool_response>': -1.74,
}
START_SCRIPTS = (
    ('Cyrillic', 2.68),
    ('Hangul', 3.46),
    ('Katakana', 3.92),
    ('Hiragana', 1.87),
    ('Han', 0.51),
    ('Thai', 3.5),
