            value = 1.48
    elif age == 1 and prev == 'Title' and token == ':':
        value = 8.28
    elif 'ّ' in token:
        value = -4.23
    elif n_arabic:
        if persian:
            value = -0.24 if token.startswith(' ') and n_arabic == 1 else -0.45
        else:
            value = -1.85 if age == 0 else -1.30
    elif token.strip() == '،':
        value = 1.00
    elif token == 'ً':
        value = -0.90
    elif token in MARKUP:
        value = MARKUP[token]
    elif prev == '<|im_start|>' and token in ('user', 'assistant', 'system'):
        value = -0.796 if token == 'user' and age == 1 else 0.0
    elif token.isspace():
        if prev == '<|im_end|>':
            closed_tool = before in ('</tool_call>', '</tool_response>')
            value = -0.38 if closed_tool else -0.06
            if age == 1:
                value = -2.35
        elif prev == '</think>':
            value = -0.46
        elif prev == '<tool_response>':
            value = -0.32
        elif prev in ('user', 'assistant') and before == '<|im_start|>':
            value = -0.12 if age == 2 else 0.08
        elif age == 0:
            value = -0.45
