"""v6: where this component (layer 1, MLP output unit 4936) goes negative and positive.

Negative: chat-template markers (turn start, <think>, </think>, </tool_response>), Arabic-script
text (strongest on the shadda diacritic U+0651, the doubled-consonant mark), and the newline
that closes a turn. Positive: the Arabic comma, and the first token of a document when that
token opens in a non-Latin script (Cyrillic, CJK, Kana, Hangul, Thai). Everything else is ~0.
"""
READS = ()

MARKERS = {"<|im_start|>": -1.5, "<think>": -1.0, "</think>": -2.0, "</tool_response>": -1.7}
SHADDA = "ّ"
ARABIC_COMMA = "،"

def is_arabic_script(text):
    return any("؀" <= ch <= "ۿ" for ch in text)

def is_non_latin_letter(text):
    return any(ch.isalpha() and ord(ch) > 0x24F for ch in text)

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else "<|endoftext|>"
    doc_start = before == "<|endoftext|>"
    if tok == "<|im_start|>":
        return None, 0.0 if doc_start else -1.5
    if tok in MARKERS:
        return None, MARKERS[tok]
    if tok == "\n" and before == "<|im_end|>":
        return None, -0.25
    if SHADDA in tok:
        return None, -4.5
    if is_arabic_script(tok):
        return None, -3.0 if doc_start else -0.8
    if tok == ARABIC_COMMA:
        return None, 1.7
    if doc_start and is_non_latin_letter(tok):
        return None, 1.5
    return None, 0.0

