"""Approximate a short-lived n+t spelling signal, not a token lookup table.

Short fragments and n/t splits are stronger than frequent whole English
words. Transliteration extends the rule to Greek ντ, Cyrillic нт, Japanese
ント and Korean 인+터. A completed cluster can affect the following token.
German 'unter' and the 'lint' family have extra responses; a double middle
dot has a separate negative response. All state resets between documents.
"""
import codecs
from functools import lru_cache

import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
VOWEL_EFFECT = {'a': -0.14, 'e': -0.09, 'i': 0.03, 'o': 0.35, 'u': 0.23}


@lru_cache(maxsize=32768)
def spelling(text):
    # Han readings are not alphabetic spellings. Theta is not tau, and
    # Cyrillic ц is an affricate, not the stop т.
    text = regex.sub(r'\p{Script=Han}', ' ', text)
    text = text.replace('θ', 'q').replace('Θ', 'Q')
    text = text.replace('ц', 'c').replace('Ц', 'C')
    return anyascii(text).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        tail, was_crossing, was_fragment, pending = '', False, False, b''
    else:
        _, tail, was_crossing, was_fragment, pending = carry

    # Complete characters whose UTF-8 bytes span token boundaries.
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'ignore', False)
    s = spelling(text)
    word = s.strip()
    # A literal backslash-n is a line-break escape, not a word-final n.
    tail = tail.replace('\\n', ' ').replace('\\r', ' ').replace('\\t', ' ')
    connected = bool(s and tail) and s[0].isalpha() and tail[-1].isalpha()

    # Long or frequent complete words weaken the token-boundary signal.
    short = max(0.0, 1.0 - max(0, len(s) - 2) / 4.0)
    if len(s) > 2:
        frequency = zipf_frequency(s, 'en')
        short *= min(1.0, max(0.0, (5.0 - frequency) / 1.5))

    value = 0.0
    crossing = connected and tail.endswith('n') and s.startswith('t')
    if crossing:
        strength = 1.79
        if len(tail) > 1 and tail[-2] in 'iou':
            strength += 1.89
        if text and regex.match(r'\p{Script=Greek}', text[0]):
            strength += 3.50
        if text.isupper():
            strength += 0.14
        if s.startswith('tr'):
            strength -= 1.04
        value += short * strength
    if connected and s.startswith('t') and tail.endswith(('nd', 'ng', 'nz', 'ns')):
        value += 0.61 * short

    fragment = 'nt' in word and len(word) <= 6
    rarity = 0.0
    if fragment:
        rarity = min(1.0, max(0.0, 5.0 - zipf_frequency(word, 'en')))
        p = word.rfind('nt')
        vowel = word[p-1:p] if p else (tail[-1:] if connected else '')
        strength = 0.20 + VOWEL_EFFECT.get(vowel, 0.0)
        if connected and vowel in ('i', 'o', 'u', 'y'):
            strength += 0.48
        value += rarity * strength
        if word == 'nt':
            value += 1.24
        if connected and tail.endswith('n') and word.startswith('nt'):
            value -= 1.06
        if first:
            value -= 0.40

    if word == 'unter':
        value += 3.48
    elif word == 'unters':
        value += 1.02
    if word == 'int' and not connected:
        value -= 0.17
    if word == 'lint' and not connected:
        value += 1.85
    if connected and tail.endswith('l') and word.startswith('int'):
        value += 2.07

    if connected and tail.endswith('nt') and (was_fragment or was_crossing):
        strength = 0.68
        if tail.endswith('unt'):
            strength += 0.31
        if tail.endswith('ent'):
            strength -= 0.44
        if was_crossing:
            strength += 0.70
        value += short * strength
    if text == '··':
        value -= 1.13

    state = (doc, (tail + s)[-5:], crossing,
             fragment and rarity > 0.5, raw[used:])
    return state, float(value)

