"""layers.1.mlp.down_proj:4937 as a detector of word fragments.

Most of the time this component is silent (it passes the causal-importance
threshold on about 0.2% of tokens). Its large activations sit on a short list
of sub-word pieces that recur inside longer words, mostly in German, French,
Greek, Russian and in names and technical words. The strongest is the German
preposition " unter" (and " Unter", as in "Unterbindung"); then pieces such as
"inter", "ont", "nt", "unt", "NT", "TR"; then weaker pieces such as "int",
"into", "cont", "tr", "ter", "lint", and single foreign letters "τ", "т".

The program predicts the activation from the current token alone:
  - a document's first token gets a small negative value (about -0.27);
  - middle-dot characters "·" get a strong negative value (about -1.1);
  - a listed fragment gets its typical positive value;
  - every other token gets 0.
It ignores context, so it captures the token-driven part of the activation.
"""

READS = ()

# Whole words that fire strongly every time.
UNTER = {" unter": 4.3, " Unter": 4.3}

# Pieces of longer words: strong, then weaker and context-dependent ones.
STRONG = {"inter": 3.0, "ont": 1.9, "ONT": 0.9, "NT": 1.7, "nt": 1.2, "unt": 1.3, "TR": 1.3}
WEAK = {
    "int": 0.5, "into": 0.5, "intr": 0.5, " intr": 0.5, "lint": 0.5,
    "cont": 0.5, " cont": 0.6, " contr": 0.4, "tr": 0.3, "ter": 0.2,
    " int": 0.2, " inter": 0.3, " mont": 0.7, " Mont": 1.0,
    "τ": 0.3, "т": 0.3,
}

DOC_START = -0.27
MIDDLE_DOT = -1.1


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    t = prefix.position
    starts_doc = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if starts_doc:
        value = DOC_START
    elif "·" in token:
        value = MIDDLE_DOT
    elif token in UNTER:
        value = UNTER[token]
    elif token in STRONG:
        value = STRONG[token]
    elif token in WEAK:
        value = WEAK[token]
    else:
        value = 0.0
    return carry, float(value)

