"""Draft 4: negative activation inside long random-looking strings of mixed case and
digits (base64 blobs, tokens, encoded data). The strength grows with the length of the
unbroken run of letters, digits and joiners, and with how often its letters and digits
switch between upper case, lower case and digit. It is zero unless the run has all three
kinds of character, which keeps out words, protein sequences and hex hashes."""
from collections.abc import Mapping

READS = ()

LETTERS_DIGITS = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789")
JOINERS = set("+/=_-")  # base64 and ids use these inside a run; they do not break it
STRENGTH = -3.2


def ramp(x, lo, hi):
    return min(1.0, max(0.0, (x - lo) / (hi - lo)))


def char_class(c):
    if c.isupper():
        return "upper"
    if c.islower():
        return "lower"
    return "digit"


def step(carry, prefix, upstream: Mapping):
    # carry: run length, counts of each class, class switches, previous class
    run, counts, switches, prev = carry if carry is not None else (0, None, 0, None)
    if counts is None:
        counts = {"upper": 0, "lower": 0, "digit": 0}
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        run, counts, switches, prev = 0, {"upper": 0, "lower": 0, "digit": 0}, 0, None
    for c in prefix.token_strings[-1]:
        if c in LETTERS_DIGITS:
            k = char_class(c)
            if prev is not None and k != prev:
                switches += 1
            prev = k
            counts[k] += 1
            run += 1
        elif c in JOINERS:
            run += 1
        else:
            run, counts, switches, prev = 0, {"upper": 0, "lower": 0, "digit": 0}, 0, None
    carry = (run, counts, switches, prev)
    n = counts["upper"] + counts["lower"] + counts["digit"]
    if min(counts.values()) == 0 or n < 2:
        return carry, 0.0
    switch_rate = switches / (n - 1)
    return carry, STRENGTH * ramp(switch_rate, 0.3, 0.6) * ramp(run, 8, 32)

