"""Component layers.1.mlp.down_proj:4941 as a short list of token rules.

The component is sparse and mixed. Its activation is large on a few kinds of token
and is read from the token itself plus the token before it:

- the URL scheme separator "://" (strongest); web-address and git-host pieces
  ("www", "git", ".git"), and ".com" right after "github" (as in github.com/...);
- the arrow "->" right after "this" (PHP "$this->");
- "self" or "this" used as an object in code, most strongly at the start of an
  indented statement ("        self.data = data");
- the English verbs "get", "got", "gets", "getting", "gotten";
- "of" after a quantifier ("one of", "each of", "any of", "two of");
- demonstratives in other languages ("esta", "questo", "cette", "ces", ...);
- the digits 2 and 6 when they follow an even digit (as in "202", "26").

Everything else predicts 0. Each class gets a value near its typical activation.
"""

READS = ()

SCHEME = "://"
WEB_PIECES = {"www", ".git", "git", " git"}
GITHUB_STEMS = {"github", '"github', " github", "ithub"}
GET_VERBS = {" get", " got", " gets", " getting", " gotten", " Get", " Got", " Getting", "Get", "got"}
SELF_REFS = {" self", "self", "(self", "\tself", "=self", "this", "\tthis", "(this"}
QUANTIFIERS = {" one", "One", " One", "one", " which", " Which", " each", " Each", "each",
               " any", " either", " neither", " two", " Two", " Both", " several", " four", " nine"}
FOREIGN_DEMONSTRATIVES = {" esta", " estas", " este", " questo", " questa", " cette",
                          " ces", " cet", " ce", " diese", " dieser", " esse"}
EVEN_DIGITS = set("02468")


def is_line_start(prev):
    """True if the previous token is indentation or ends a line."""
    return prev.strip() == "" or prev.endswith("\n")


def rule(token, prev):
    """Activation of this component on `token`, given the token before it."""
    if token == SCHEME:
        return 2.7
    if token == ".com":
        return 3.0 if prev in GITHUB_STEMS else 0.3
    if token in WEB_PIECES:
        return 1.0
    if token == "->" and prev.strip() in ("this", "$this"):
        return 2.0
    if token in (" self", "self") and is_line_start(prev):
        return 2.0
    if token in GET_VERBS:
        return 0.7
    if token in SELF_REFS:
        return 0.8
    if token == " of" and prev in QUANTIFIERS:
        return 1.0
    if token in FOREIGN_DEMONSTRATIVES:
        return 0.6
    if token in ("2", "6") and prev in EVEN_DIGITS:
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if len(prefix) > 1 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""  # a new document starts here: the token before belongs to another one
    return None, float(rule(token, prev))

programs.sol:
"""Approximate a token's uncontextualized, document-onset response.

The signal lasts through a repeated initial token, then is normally zero.
Its amplitude depends on token shape, English word frequency, and a few
recognizable opening constructions: articles, questions, and module imports.
The initial digit sequence '12' has a separate, strong negative response.
These are coarse lexical estimates, not an exact token lookup.
"""
import math
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()
ARTICLES = {'a', 'an', 'the'}
QUESTIONS = {'what', 'when', 'where', 'who', 'whom', 'whose',
             'which', 'why', 'how'}
# The ten decimal digits have distinct onset responses, in numeric order.
DIGIT_ONSETS = (0.76, -2.70, 1.26, -1.56, 0.07,
                -0.64, 0.37, -2.21, -0.85, -3.88)
SIGN_ONSETS = {'#': 8.4, '<': 7.3, '_': 4.8, "'": 4.6,
               '"': 2.7, ':': 0.6, ',': 1.9, '.': 2.4,
               '-': 2.2, '/': 2.5}


@lru_cache(maxsize=16384)
def onset(text):
    s = text.strip()
    if not s:
        if text == ' ':
            return -0.37
        if text and all(c == ' ' for c in text):
            return 2.85 if len(text) == 2 else 5.9
        if text == '\r':
            return -1.9
        if text == '\r\n':
            return 5.2
        return 1.8 if text.count('\n') > 1 else 2.6
    if text.startswith('<|'):
        return 6.9 if text == '<|endoftext|>' else 5.8
    if len(text) == 1 and text in '0123456789':
        return DIGIT_ONSETS[int(text)]
    # Module and namespace introductions at the left edge of source code.
    if text in {'import', 'package', 'using'}:
        return 16.9 if text == 'import' else 12.7
    if regex.match(r'\p{Latin}', s):
        capital = s[0].isupper()
        value = (1.8 + 0.61 * zipf_frequency(s, 'en')
                 + 0.76 * capital - 0.84 * s.isupper()
                 - 1.12 * text.startswith(' ') + 0.87 * math.log1p(len(s)))
        if s.lower() in ARTICLES:
            value += 2.11
        if capital and not s.isupper() and s.lower() in QUESTIONS:
            value += 3.44
        return value
    if s[0].isalpha():
        return 3.4
    if '\n' in text and s[0] in '.:':
        return 0.3
    return SIGN_ONSETS.get(s[0], 2.3)


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or doc != carry[0]:
        value = onset(text)
        return (doc, token, text, text, 0, True, value), value
    _, first_token, first_text, previous, age, uniform, initial = carry
    age = min(age + 1, 3)
    uniform = uniform and token == first_token
    value = initial if uniform else 0.0
    if age == 1 and first_text == '1' and text == '2':
        value = -16.2
    elif age == 2 and first_text == '1' and previous == text == '2':
        value = -3.1
    return (doc, first_token, first_text, text, age, uniform, initial), value

"""A tokenization-sensitive 'how to' / Chinese manner-word detector.

English 'to' following 'how' gets a positive pulse, stronger after How
and after a word without a leading space.  Chinese 如何 and 何, plus
some manner/demonstrative and present-time expressions, also get pulses.
There are separate lexical pulses for Chinese 'best', 'reading', and 'image'.
At document starts a separate, usually negative estimate uses only case,
spacing, and character type.  Other lexical variation is left at zero.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0
    how = previous.strip().lstrip('/_-')
    if word.lstrip('_-').lower() == 'to' and how.lower() == 'how':
        value = 1.05
        if not previous.startswith(' '):
            value += 1.0
        if how[:1].isupper():
            value += 1.6
        # Title case, compounds, and URL paths have different strengths.
        if word == 'To':
            value *= 0.55 if token[0].isspace() else 0.12
        elif word == 'TO':
            value *= 0.8
        elif word.startswith('_'):
            value *= 0.45
        elif word.startswith('-') and not previous.startswith('/'):
            value *= 0.5
    elif word.endswith('如何'):
        value = 3.3 if word == '如何' else 2.4
    elif word == '何':
        value = 4.8 if previous.endswith('如') else 1.25
    elif word in ('怎样', '怎樣', '为何', '為何'):
        value = 1.2
    elif word == '前' and previous.endswith(('当', '當')):
        value = 3.5
    elif word == '目前':
        value = 1.0
    elif word in ('当前', '當前'):
        value = 1.4
    elif word == '如此' or (word == '此' and previous.endswith('如')):
        value = 2.0
    elif word in ('此', '因此'):
        value = 0.6
    elif word == '此外':
        value = 0.3
    elif word == '如今':
        value = 1.4
    elif word in ('近年来', '近年來'):
        value = 0.85
    # Additional, weaker Chinese vocabulary responses.
    elif word.endswith('最佳'):  # 'best'
        value = 2.0 if word == '最佳' else 1.4
    elif word in ('阅读', '閱讀', '推荐阅读', '推薦閱讀'):
        value = 1.2
    elif word in ('图像', '圖像'):  # 'image'
        value = 2.7

    if carry is None or carry[0] != doc:
        # With no left context, the component tends to write negatively.
        if word.isascii() and word.isalpha():
            value = -0.25 if token[0].isspace() else -0.4
            if word.isupper():
                value -= 0.2
        elif token.isspace():
            value = -0.25
        elif word.isdigit():
            value = -0.17
        elif word.startswith('<|'):
            value = -0.47
        else:
            value = -0.1 if word.isascii() else -0.24
    return (doc, token), value

programs.haiku:
"""Fires on "how" (how-to phrasing) and on a few words for "currently / this".

Biggest responses:
- 何 and 如何 ("how", as in 如何 / 怎么做 "how to do"): about 3 to 4.
- " to" right after "how" ("How to ...", "show you how to ..."): about 1,
  and about 3 when it opens a sentence ("How to").
- 如此 ("so / like this"): about 2.
- 目前 / 当前 ("currently") and 此 ("this"): about 1.
Everything else is predicted as 0, since the component is quiet on ordinary text.
"""

READS = ()

HOW_WORDS = {"何": 3.0, "如何": 3.0, "如此": 2.0}
CURRENT_WORDS = {"目前": 1.0, "当前": 1.0, "此": 0.8}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if tok in HOW_WORDS:
        value = HOW_WORDS[tok]
    elif tok.strip() == "to" and prev.lower() == "how":
        value = 3.0 if prev == "How" else 1.0
    elif tok in CURRENT_WORDS:
        value = CURRENT_WORDS[tok]
    else:
        value = 0.0
    return carry, float(value)

