"""Approximate a spelling response dominated by time and body word families.

Temporal, temps, corpus and related forms receive negative values. Adjacent
fragments also count: temp + or..., cor + p..., corpor + a. Similar letter
sequences receive weaker responses. Three formatting rules cover repeated
middle dots, an initial spaced period, and an initial Title: header.
Other positions stay near zero. Positive responses and longer-context
variation are not reconstructed. State resets at document boundaries.
"""
READS = ()


def response(text, previous, position):
    s = text.strip().lower()  # Current spelling fragment
    p = previous.strip().lower()  # Previous spelling fragment
    if (s and set(s) == {'·'} and len(s) >= 2
            and p and set(p) == {'·'}):
        return -1.422
    if position == 0 and text == ' .':
        return -3.135
    if position == 1 and previous == 'Title' and text == ':':
        return -3.84

    # Complete tokens in the time (tempus) and body (corpus) families.
    if s == 'temporal':
        return -6.302
    if s in ('tempor', 'empor'):
        return -5.068
    if s.startswith('contempor'):
        return -1.138
    if s.startswith('temporar') or s.startswith('emporary'):
        return -0.976
    if s == 'temps' and text[0].isspace():
        return -3.456
    if s == 'tempo':
        return -1.557
    if s == 'temper' or s.startswith('tempered'):
        return -1.096
    if s == 'temp':
        return -0.346
    if s in ('corpus', 'korpus'):
        return -4.494
    if s in ('corp', 'corpo', 'corps', 'corpor', 'corpora'):
        if s == 'corp' and text.strip()[0].isupper():
            return -0.846
        if s == 'corps':
            return -1.763
        return -3.073
    if s.startswith('corporat'):
        return -0.519 if s.startswith('corporate') else -0.118
    if s in ('cuerpo', 'cuerpos'):
        return -1.856
    if s.startswith(('empir', 'emper')):
        return -0.261

    # The spelling continues without a word boundary.
    joined = (text and previous and text[0].isalpha()
              and previous[-1].isalpha())
    if joined:
        if p.endswith('temp') and s.startswith('or'):
            return -8.645
        if p == 'emp' and s.startswith('oral'):
            return -8.205
        if p.endswith('temp') and s.startswith('o'):
            return -3.674
        if p == 'corpor' and s in ('a', 'al'):
            return -5.849
        if p.endswith(('corp', 'corpor')):
            return -0.06
        if p in ('em', 'tem') and s.startswith('pos'):
            return -7.031
        if p in ('em', 'tem') and s.startswith(('per', 'por', 'ps')):
            return -3.444
        if p in ('em', 'tem') and s.startswith('p'):
            return -1.015
        if p.endswith('fem') and s.startswith('or'):
            return -2.681
        if p.endswith(('cor', 'kor', 'uer')) and s.startswith('p'):
            return -4.228
        if p.endswith('c') and s.startswith('orpor'):
            return -1.337
        if p.endswith(('am', 'ym')) and s.startswith('p'):
            return -0.342
        if p.endswith(('op', 'arp')) and s.startswith('us'):
            return -1.871
        if p.endswith('emp'):
            return -0.206
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        _, previous, position = carry
    text = prefix.token_strings[-1]
    value = response(text, previous, position)
    return (doc, text, position + 1), value

"""Heuristics for predicate and modifier endings, chiefly Japanese and Korean.

Japanese plain verbs, negatives, past forms and adjectives receive positive
values; polite endings are weak. Korean adnominal endings are another strong
cue. Chinese genitives and German/Turkish suffixes are weaker cues. JMdict
and WordNet distinguish some Japanese adjectives/verbs from word fragments.
There is also a strong formatting response to document-initial 'Title:'.
This is not a full grammatical parser. Unrecognized tokens receive zero.
"""
from functools import lru_cache
import re
import regex
import jmdict
import wordnet

READS = ()

@lru_cache(maxsize=50000)
def word_kind(word):
    glosses = jmdict.glosses(word)
    if not glosses:
        return ''
    if glosses[0].startswith('to '):
        return 'verb'
    first = glosses[0].split()[0].lower().strip('(),')
    return 'adjective' if 'adjective' in wordnet.parts_of_speech(first) else ''

def ending_kind(text):
    for size in range(2, min(len(text), 7) + 1):
        kind = word_kind(text[-size:])
        if kind:
            return kind
    return ''

@lru_cache(maxsize=100000)
def token_value(raw):
    s = raw.strip()
