        return 0.0
    if s == '的':
        return 0.34
    if s in {'目的','标的'}:  # 'purpose' and 'target', not the particle de
        return -1.7
    if s.endswith('的'):
        return 0.1
    if s in {'之','之中','의'}:
        return 0.25
