        if s.endswith(('ます','ました','ません','です','でした')):
            return 0.2
        if s in {'の','この','その','あの','どの'}:
            return 0.35
        if s.endswith('の'):
            return 0.7
        if s.endswith('な'):
            return 2.8 if s=='な' else 1.7
        if s=='だ':
            return 2.2
        if s=='んだ':
            return 4.5
        if s in {'る','む','ぬ','す','く','ぐ','ぶ','つ','う'}:
            return 4.8 if s in 'るむぬ' else 2.1
        if s=='た':
            return 2.6
        if s.endswith('ない'):
            return 5.4
        if s.endswith(('ている','でいる','ていく','でいく','てくる','てしまう')):
            return 5.6
        if s in {'いた','きた','った','来た','ていた'}:
            return 6.6
        if s.endswith('た') and s not in {'また','あなた','かた','どなた','なた'}:
            return 4.4
        if s in {'という','らしい'}:
            return 1.5
        if s in {'そう','こう','どう','よう','もう','なく','よく','すぐ',
                 'おそらく','まったく','くらい','ぐらい','につ','お互い','互い'}:
            return 0.0
        if s.endswith('ろう'):
            return 3.3
        if s=='いく':
            return 5.6
        if s.endswith('る'):
            return 4.1
        if s.endswith(('たい','しい')):
            return 3.8
        if s in {'いい','よい'}:
            return 3.2
        if len(s)>1 and s[-1] in 'うくぐすつぬぶむ':
            if word_kind(s)=='verb' or s[0] in 'がをに':
