    elif s=='く' and ending_kind(tail+s)=='verb':
        value = 4.4
    elif s=='く' and ending_kind(tail+'い')=='adjective':
        value = 1.0
    elif s=='た' and tail.endswith(tuple('しせれけげてでべめびみじえ')):
        value = 6.1
    elif s=='た' and tail.endswith(tuple('あかがさざただなはばぱまやらわうくぐすつぬぶむるこごほぼも')):
