programs.haiku:
"""Inflected verb and adjective endings in Japanese and Korean.

The component fires on the last character of a predicate word that is still being
inflected: in Japanese, the final kana of a verb or adjective (dictionary, past,
negative, and -te/-na forms such as 食べる, 大きい, 行った, 知らない, 静かな), and in
Korean, the final syllable of an adnominal (modifier) verb form such as 하는, 있는, 한,
할, 되는. It is strongest on the endings る, む, ぬ, た, い, and weaker on な, う, く,
だ, つ, す. Polite endings (ます, です) and particles (の, は, を, て) stay near zero.
Other scripts, and kanji, do not fire. The values are the mean activations measured on
training text."""

READS = ()

# Final kana of a Japanese predicate, with its mean activation on training text.
JAPANESE_ENDINGS = {
    "る": 4.5, "む": 4.5, "ぬ": 4.0, "た": 3.5, "い": 3.5,
    "な": 2.5, "す": 2.5, "う": 1.8, "く": 1.9, "だ": 1.7, "つ": 1.4,
}
# Final syllables of Korean adnominal verb forms (modifiers before a noun).
KOREAN_MODIFIER_ENDINGS = set("는한할던된될운난온린진준낀낼인은있")


def is_hiragana(text):
    return bool(text) and all("぀" <= ch <= "ゟ" for ch in text)


def has_kanji(text):
    return any("一" <= ch <= "鿿" for ch in text)


def is_hangul(ch):
    return "가" <= ch <= "힣"


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1].strip()
    if not text:
        return carry, 0.0
    last = text[-1]
    # Polite endings (ます, です and their forms) are not verb endings here.
    if is_hiragana(text) and len(text) > 1 and last == "す":
        return carry, 0.0
    if (is_hiragana(text) or has_kanji(text)) and last in JAPANESE_ENDINGS:
        return carry, float(JAPANESE_ENDINGS[last])
    if is_hangul(last) and last in KOREAN_MODIFIER_ENDINGS:
        return carry, 3.0
    return carry, 0.0

