import re
import regex

READS = ()
KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')


def activation(token, before):
    japanese = bool(KANA.search(before[-64:] + token))
    word = token.strip()
    if word in ('—', '–', '-') and token.startswith(' '):
        if re.search(r'[.!?]\s*$', before):
            return -0.35  # dash after sentence
        if regex.search(r'\p{Script=Cyrillic}', before):
            return -0.5  # cyrillic dash
        if re.search(
            r'\b(der|die|das|und|ist|nicht|sich|den|dem|ein|eine|auch|az|hogy|és)\b',
            before.lower(),
        ):
            return -1.07  # german hungarian dash
        return 0.0
    if len(word) > 1 and set(word) == {'·'}:
        return -0.59  # centered dots
    if word in ('거', '것', '것이', '것을', '것은', '것으로', '걸', '건'):
        if word in ('거', '건') and not token.startswith(' '):
            return 0.0  # Usually an internal word fragment here.
        if before.endswith(('는', '은')):
            return -5.03  # korean attributive nominalizer
        last = before[-1:]
        if last and '가' <= last <= '힣' and (ord(last) - ord('가')) % 28 == 8:
            return -1.16  # Future modifier: final consonant ㄹ.
        return -2.86  # korean nominalizer
