        if re.search(
            r'[ıİğĞşŞ]|\b(bir|bu|için|ile|olan|çok|daha|gibi|değil)\b',
            before.lower(),
        ):
            return 2.14  # turkish conjunction
        return 0.0

    if word in ('、', '，', ',') and japanese:
        if before.endswith('は'):
            return -2.31  # topic comma
        if re.search(
            r'(ので|から|が|けど|のに|なら|と|で|も|に|て|ながら|たら|や)$', before
        ):
            return -0.98  # clause comma
        if re.search(r'(しかし|また|なお|など|ため)$', before):
            return 0.0  # transition comma
        return 0.9  # list comma
    if word in ('のです', 'のだ', 'んです', 'わけ', 'わけで', 'わけです'):
        return -4.53  # explanatory
    if word == 'んだ':
        if before.endswith(tuple('ういえおるたな')):
            return -4.53  # explanatory
        return 0.0  # Otherwise often part of an ordinary past-tense verb.
    if word in ('よ', 'ですよ', 'よね'):
        return -1.19  # final particle
    if word in (
        'ので', 'ないので', 'ため', 'けど', 'のに', 'のですが', 'んだけど'
    ):
        return -1.27  # Causal/concessive connective.
    if word in ('だろう', 'はず', 'はずです'):
        return -2.77  # speculative
    if word in ('のか', 'のかな', 'のでしょうか'):
        return -1.46  # question nominalizer
    if word in (
        'のは', 'のが', 'のも', 'するのは', 'するのが', 'というのは', 'というのが'
    ):
        return -2.24  # Nominalizing の plus a particle.
    if word in ('ことも', 'ことは', 'ことで', 'ことが', 'ということ'):
        return -1.28  # abstract nominalizer
    if word == 'もの':
        if re.search(r'(年|人|回|通り|個|枚|匹|本|日)$', before):
