        if before.endswith('い'):
            return 0.88  # もの after adjective-like い.
        if before.endswith(('る', 'た', 'な')):
            return -0.76  # もの after other attributive endings.
        return 0.0  # Other uses of もの.
    if word in ('の方が', '方が', 'ほうが'):
        return -1.75  # comparison
    if word in ('よう', 'ように', 'ようです'):
        return -1.28  # resemblance
    if word in ('という', 'と言', 'いう', 'と思', 'と思う', 'だと思う'):
        return -1.07  # quotative
    if word in ('不', '無', '没', '无', '不可能'):
        return 0.43  # negation
    if word in ('上の', '下の', '前の', '後の', '中の'):
        return 1.81  # Spatial/temporal attributive.
