import re

READS = ()
HEADERS = {
    'for': -12.6, 'foreach': -12.4, 'if': -7.7, 'elseif': -5.5,
    'while': -7.7, 'switch': -11.9, 'catch': -10.8,
    'function': -7.0, 'using': -14.0,
