"""Draft v2: how strongly one down-projection component of layer 1 is active on the
current token, judged from the token's text alone.

It is strongest on literal escape sequences in code or data (a backslash followed by
n, t or r, as in "\\n" or "\\t" inside a string), and on the pieces of words that a
tokenizer splits up (word fragments without a leading space, and non-English letters).
Ordinary spaced English words are weakly positive; function words, digits and
punctuation sit near zero.
"""

READS = ()

FUNCTION_WORDS = {
    "the", "a", "an", "of", "to", "in", "and", "or", "is", "are", "was", "that", "it",
    "as", "for", "on", "with", "by", "at", "be", "this", "from", "not", "but",
}


def step(carry, prefix, upstream):
    t = prefix.token_strings[-1]
    s = t.strip()
    if "\\" in t:
        value = 1.6  # escape sequence or backslash in code/regex/strings
    elif not s or s.isdigit() or not any(c.isalpha() for c in s):
        value = 0.1  # whitespace, digits, punctuation
    elif any(ord(c) > 127 for c in s):
        value = 0.33  # non-ASCII letters (other scripts, accents)
    elif not t.startswith(" "):
        value = 0.25  # fragment of a split word
    elif s.lower() in FUNCTION_WORDS:
        value = 0.03  # the, of, to, and ...
    else:
        value = 0.19  # a spaced English word
    return carry, value

