"""Partitioning and configuration, strongest at the word linking a whole to parts.

The largest response is 'into' after division, grouping, or decomposition.
Arrangement gives smaller responses on 'in', 'so', 'such', and 'according'.
Constituent phrases such as 'consists of' get smaller responses, with a
negative response on 'consists' itself. Chinese division expressions are
positive, while 分量 ('quantity') is negative at 量. Most other tokens get
zero. These approximate rules use dictionary lemmas and at most eight words
of the current clause; text history resets at every document boundary.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
DIVISION = {
    'divide', 'subdivide', 'partition', 'split', 'separate', 'segment',
    'decompose', 'decomposable', 'division', 'separation', 'stratify',
    'classify', 'categorize', 'categorise', 'group', 'cluster', 'randomize',
}
CONFIGURE = {'arrange', 'organize', 'organise', 'sort', 'order'}
FACTOR = {'factor', 'factorize', 'factorise', 'factorization'}
CUT = {'cut', 'slice', 'chop'}
POSITION = {'place', 'put', 'position', 'dispose', 'situate', 'assemble'}
FORM = {'dress', 'pack', 'package', 'expand', 'summarize', 'range'}
BE = {'be', 'is', 'are', 'was', 'were', 'been', 'being'}


@lru_cache(maxsize=20000)
def roots(word):
    return frozenset((word, *wordnet.base_forms(word)))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    t = token.strip()
    value = 0.0
    links = {'into', 'in', 'so', 'such', 'according', 'of', 'to', 'as',
             'divided', 'classified', 'consist', 'consists', 'consisting'}
    if t in links and (token.startswith(' ') or not text or
                       not text[-1].isalpha()):
        clause = re.split(r'[.!?;,:]', text)[-1]
        words = re.findall(r'[A-Za-z]+', clause.lower())[-8:]
        prev = words[-1] if words else ''
        root = roots(prev)
        recent = set().union(*(roots(w) for w in words))
        # Bare 'order' usually names a noun rather than an arrangement action.
        config = any(roots(w) & CONFIGURE for w in words
                     if w not in {'order', 'group'})
        if t == 'into':
            value = -0.18
            if recent & DIVISION:
                value = 8.0
            elif recent & FACTOR:
                value = 5.8
            elif recent & CONFIGURE:
                value = 6.0
            elif recent & CUT:
                value = 7.0 if prev == 'cut' else 3.0
            elif 'break' in recent:
                value = 6.0 if 'down' in words else 2.6
            elif root & {'fall', 'shape', 'branch'}:
                value = 2.5
        elif t == 'in':
            value = 0.015
            if prev in BE:
                value = 0.45 if prev == 'be' else 0.10
            if root & POSITION:
                value = 0.6
            if root & FORM or prev == 'different':
                value = 1.1
            if config:
                value = 2.5 if root & CONFIGURE else 0.5
            if prev == 'available':
                value = 1.7
            if 'come' in root:
                value = 1.5 if prev == 'came' else 3.1
        elif t in {'so', 'such'}:
            value = 0.08
            if prev in {'and', 'if'}:
                value = -0.3
            elif t == 'such' and prev in BE:
                value = 0.7
            elif prev.endswith('ed'):
                value = 0.5 if t == 'so' else 1.2
            if config:
                value = 2.3
        elif t == 'according':
            value = 0.5
            if prev.endswith('ed'):
                value = 1.1
            if config or recent & DIVISION:
                value = 2.6
        elif t == 'of':
            if prev == 'terms':
                value = 0.95
            elif 'consist' in root or prev == 'composed':
                value = 0.6
            elif words[-2:] == ['made', 'up']:
                value = 0.9
        elif t == 'to' and 'assign' in root:
            value = 0.9
        elif t == 'as' and root & {'classify', 'categorize', 'categorise'}:
            value = 0.5
