RELATIVE_LINKERS = {'que', 'qui', 'che', 'что'}
CLAUSE_OPENERS = {'which', 'who', 'if', 'when', 'where', 'because',
                  'although', 'whereas', 'whether'}
AUXILIARIES = {'would', 'should', 'could', 'must', 'has', 'have', 'had',
               'can', 'will', 'may', 'might'}
PREPOSITIONS = {'of', 'to', 'by', 'in', 'on', 'at', 'from', 'with', 'about',
                'into', 'over', 'under', 'through', 'between', 'after', 'before',
                'for', 'since', 'until', 'despite', 'without', 'beyond'}
