    if word in RELATIVE_LINKERS:
        return 1.10
    if word == 'that':
        return 0.0 if previous in DEMONSTRATIVE_CONTEXT else 0.9
    if word == 'but':
        return 0.98
    if word == 'then':
        return 0.10 if previous in PREPOSITIONS | {'just'} else 0.72
    if word == 'so':
        if previous in {'if', 'even', 'like', 'do', 'did', 'doing', 'think'}:
            return 0.10
        return 0.72 if capital else 0.40
    if word == 'now':
        if previous in PREPOSITIONS:
            return 0.07
        return 0.54 if capital else 0.34
    if word in {'as', 'why'}:
        return 0.65
    if word in AUXILIARIES:
        return 0.58
    if word in {'is', 'are', 'was', 'were', 'be', 'been', 'being'}:
        return 0.08 if previous == 'that' else 0.40
    if word in {'including', 'means', 'saying', 'say', 'think'}:
        return 0.48
    if word == 'for':
        return 0.43
    if word in PREPOSITIONS:
        return 0.23
    if word in {'thus', 'therefore'}:
        return 0.23
    if word in {'however', 'wait', 'though'}:
        return 0.11
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = comma_value(tail) if token == ',' else 0.0
