"""layers.1.mlp.down_proj:4956 -- the comma that opens a new clause.

This component reads "is a comma about to start a new clause here?" and writes a
positive push into the residual stream when the answer is yes. It fires on a comma
placed right after a word that links it to what follows:

  * conjunctions and relative words ("... and, as a result", "which, unlike", "who,
    when", "because,", "if,"): strongest, about 1.3 nats of activation;
  * sentence connectives and other conjunctions ("Then, we", "So, the", "or,",
    "und,", "que,"): medium, about 0.5;
  * "that" introducing a clause ("reported that, ..."): about 0.9; but "that" as a
    demonstrative after a preposition or "do" ("after that, ...") gives nothing;
  * weaker cases such as "thus,", "to,", "is,": about 0.2.

Every other token is about zero, except the first token of each document (right after
<|endoftext|>, or the first token of a row), which sits slightly below zero.

Everything here is a rule over the words in the prefix; nothing is looked up by token id.
"""
READS = ()

# Conjunctions and relative words that start a clause the comma then sets off.
STRONG = {"and", "but", "which", "who", "whom", "whose", "because", "when", "where", "since", "if"}
# Sentence connectives, "or", and conjunctions in other languages.
MEDIUM = {"or", "then", "so", "now", "may", "can", "should", "would", "must", "are", "of",
          "или", "und", "oder", "che", "que", "что", "и", "mais"}
# Weak cases: discourse adverbs and a few words that often precede an aside.
WEAK = {"thus", "therefore", "hence", "to", "is", "yet", "though", "as"}
# Words before "that" that make it a demonstrative ("after that,") rather than a clause opener.
DEMONSTRATIVE_CONTEXT = {"after", "to", "of", "with", "from", "about", "for", "than", "before",
                         "at", "on", "in", "by", "like", "do", "did", "doing", "done", "get"}
DOC_START = -0.15  # first token of a document: a small constant offset


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, DOC_START
    if toks[-1] != ",":
        return carry, 0.0
    prev = toks[-2].strip().lower()
    if prev in STRONG:
        return carry, 1.3
    if prev == "that":
        before = toks[-3].strip().lower() if len(toks) > 2 else ""
        return carry, 0.0 if before in DEMONSTRATIVE_CONTEXT else 0.9
    if prev in MEDIUM:
        return carry, 0.5
    if prev in WEAK:
        return carry, 0.2
    return carry, 0.0

