when that token opens code, a comment, a directive or markup; ~0 when it opens ordinary prose."""
READS = ()

BLOCK_COMMENT = {'/*', '/**', '/*\n', '/**\n', '"""', '"""\n', "'''", "'''\n"}
LINE_COMMENT = {'#', '##', '//', '#!/', '--', '**'}
IMPORT_WORDS = {'import', 'package', 'using', 'from', 'const', 'var', 'export'}
CODE_WORDS = {'def', 'class', 'int', 'function', 'module', '#include', '#define', '#pragma', '#ifndef'}
MARKUP = {'<?', '<', '---\n', '```'}

def step(carry, prefix, upstream):
    t = prefix.position
    if not (t == 0 or prefix.token_ids[-2] == 151643):
        return None, 0.0
    s = prefix.token_strings[t]
    if s in BLOCK_COMMENT:
        v = 10.0
    elif s in IMPORT_WORDS:
        v = 8.0
    elif s in LINE_COMMENT:
        v = 7.0
    elif s in CODE_WORDS:
        v = 4.0
    elif s in MARKUP:
        v = 3.0
    elif len(s) >= 3 and s.strip() == '':
        v = 2.0
    else:
        v = 0.0
