"""Alpha detector: fires on the word 'alpha' (and its spellings alph- and alfa-, also in Russian,
Greek, Korean, Japanese and Chinese script) and on the Greek letter alpha used as a symbol in
English or maths text. Strongest on capitalised or space-preceded 'alpha'."""
import unicodedata

READS = ()
SPELLINGS = ("alpha", "alph", "alfa", "альфа", "алфа", "αλφα", "λφα", "アルファ", "알파", "阿尔法", "阿爾法")


def is_greek(ch):
    return unicodedata.name(ch, "").startswith("GREEK")


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    word = "" if (carry is None or new_doc) else carry
    if not s[:1].isalpha():
        word = ""
    word += "".join(ch for ch in s if ch.isalpha()).lower()
    if word.endswith(SPELLINGS) and not word.endswith("ralph"):
