"""A lexical response/completion approximation.

'answer' is much more negative as a requested action than as a noun.
Chinese completion/answer verbs also give negative pulses.  'Read More'
and final-answer headings have the opposite sign.  Spelling, formatting,
and code-start side responses are modelled separately.  Other tokens get zero.
"""
import re

READS = ()


def pulse(token, previous, recent, first):
    word = token.strip()
    prev = previous.strip().lower()
    lower = word.lower()
    if lower == 'answer':
        if word == 'Answer':
            if prev == 'final':
                return 1.43
            if prev == 'correct':
                return 0.74
            return -0.4
        if prev == 'correct':
            return 0.0
        if prev == 'final':
            return 0.18
        if prev == 'to':
            # Reading instructions are a particularly strong answering cue.
            if re.search(r'\bread\b.*\bfollowing\b', recent[-180:], re.I):
                return -10.0
            if re.search(r'\b(read|use)\b', recent[-100:], re.I):
                return -4.0
            return -2.0
        if prev == 'please':
            return -4.4
        if prev in {'and', 'then'}:
            return -2.3
        if prev == 'me' and re.search(r'\bhelp\b', recent[-50:], re.I):
            return -3.5
        if prev in {'will', 'shall', 'must', 'can', 'could', 'let'}:
            return -0.8
        if token == 'answer' and (first or previous.endswith('\n')):
            return -1.5
        return -0.3
    if lower == 'answering':
        return -0.6
    if lower == 'complete' and prev == 'to':
        return -0.5
    if '完成' in word and len(word) <= 5:
        return -2.4
    if word.startswith(('实现', '實現')):
        return -0.8
    if word == '回答':
        return -1.3
    if word == '答案':
        return -0.6
    if word in {'解决', '解決', '阅读', '閱讀'}:
        return -0.5
    if word == 'More' and prev == 'read':
        return 1.9
    if lower in {'content', 'document'} and prev == 'full':
        return 1.0
    # A repeatable lexical accident: the misspelling 'Huamn'.
    if token == 'am' and previous.strip() == 'Hu':
        return -1.34
    if token == 'n' and recent.endswith('Huam'):
        return -0.12
    if word == '··':
        return 0.8
    # At a fresh row/document, a few programming-language starters spike.
    if first:
        if token == 'int':
            return 5.2
        if token == 'string':
            return 2.8
        if token == 'def':
            return 2.18
        if token in {'package', 'using'}:
            return 1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, recent = ('', '') if first else carry[1:]
    token = prefix.token_strings[-1]
    value = pulse(token, previous, recent, first)
    return (doc, token, (recent + token)[-200:]), value

