"""Layer-1 MLP unit 4960 (down_proj): an "answer / complete" detector.

It goes strongly negative on the word "answer" used as a verb ("to answer", "please
answer", "help me answer"), and on Chinese verbs of finishing or answering a task
(完成 complete, 实现 achieve, 回答 answer, 解决 solve). It is mildly negative on
"Hu|am|n" (the split name of the entity type "Human"). It is positive on runs of middle
dots (··, dot leaders), on "Read More", and on the first token of a document when that
token is a programming keyword (int, string, def, using, package ...). Everything else
is 0.
"""
READS = ()

VERB_CUES = {" to", "To", " please", " then", " and", " me"}
TASK_VERBS_ZH = {"完成": -2.4, "已完成": -3.8, "完成了": -2.5, "顺利完成": -2.0,
                 "回答": -1.3, "实现": -0.7, "实现了": -1.1, "解决": -0.5}
CODE_KEYWORDS = {"int", "string", "def", "using", "package", "import", "char", "INT",
                 "void", "public", "class", "return", "static", "struct", "bool", "float",
                 "double", "const", "function", "namespace", "#include", "node", "secret"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    first = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if first:
        return None, (1.0 if tok in CODE_KEYWORDS else 0.0)
    if tok == " answer":
        return None, (-2.5 if prev in VERB_CUES else 0.0)
    if tok in TASK_VERBS_ZH:
        return None, TASK_VERBS_ZH[tok]
    if tok == "am" and prev == " Hu":
        return None, -1.3
    if tok == "··":
        return None, 0.8
    if tok == " More" and prev == " Read":
        return None, 1.6
    return None, 0.0

