"""Sparse, local detectors for legal prose and scraped-page boilerplate.

Positive responses mark Chinese regulations, enforcement and related legal
collocations. Negative responses mark forum navigation/posting-source labels.
A few explicit markup and repeated-punctuation patterns have small responses.
Everything else is quiet. Broad lexical and document-initial variation
is deliberately left unexplained.
"""
import re

READS = ()
LEGAL = re.compile(
    r'法律|宪法|憲法|条例|條例|规定|規定|法规|法規|行政|政府|司法|'
    r'法院|判决|判決|裁定|刑|有关|有關|相关|相關|依法|制度|部门|部門'
)
CODE = re.compile(
    r'代码|代碼|程序|函数|函數|命令|脚本|腳本|语句|語句|'
    r'Python|Java|SQL|Sql|python|javascript|软件|軟體|return|echo|[{}]'
)


def response(token, before, first):
    word = token.strip()
    previous = before.rstrip()
    legal = bool(LEGAL.search(before))
    if token == '\x00' and first:
        return 2.90
    if word and set(word) == {'·'} and len(word) > 1:
        return 0.57 if not before or set(before) == {'·'} else 0.0
    if token == '<think>':
        return 0.235
    if token in {'<tool_call>', '</tool_call>', '<tool_response>'}:
        return -0.10
    if token == '</tool_response>':
        return 0.06

    # Chinese legal vocabulary: distinguish enforcing rules from running code.
    if '规定' in word or word == '規定':
        if previous.endswith(('国家', '國家', '特别', '特別')):
            return 2.4
        if CODE.search(before):
            return 0.25
        return 1.5 if legal else 0.55
    if word in {'执行', '執行'}:
        if CODE.search(before):
            return 0.15
        return 1.8 if legal else 0.8
    if word in {'实施', '實施', '施行'}:
        return 0.6 if legal else 0.2
    if word in {'法规', '法規'}:
        return 1.5 if legal else 0.8
    if word in {'条例', '條例', '规程', '規程'}:
        return 0.3
    if word == '实施方案':
        return 0.65
    if word in {'文件', '文書', '文书'}:
        if previous.endswith(('规范性', '規範性')):
            return 2.9
        if previous.endswith('法律'):
            return 1.7
    if word in {'解释', '解釋'} and '法律' in before:
        if previous.endswith(('问题的', '問題的')):
            return 4.8
    if word in {'行为', '行為'} and previous.endswith('行政'):
        return 2.3
    if word in {'实际', '實際'}:
        if previous.endswith(('结合', '結合', '联系', '聯繫', '具体',
                              '具體', '工作', '我行')):
            return 0.9
    if word in {'款', '项', '項'}:
        if re.search(r'第[^。；;\n]{0,14}$', previous):
            return 1.5
    if word == '稿' and previous.endswith(('意见', '意見')):
        return 0.6
    if word in {'适用', '適用'} and legal:
        return 1.0
    if word.lower() == 'regulations':
        return 0.6 if re.search(r'law|rules|section|tax|under', before, re.I) else 0.15

    # Web-page labels, rather than ordinary uses of "posts" or "reputation".
    if word in {'from', 'by'}:
        if re.search(r'\bposts$', previous, re.I):
            if word == 'from':
                if previous.lower().endswith('showing posts'):
                    return -10.0
                return -3.3 if previous.lower().endswith('display posts') else -0.5
            return -2.0 if re.search(r'(latest|#) posts$', previous, re.I) else -0.7
        if re.search(r'\bposted$', previous, re.I):
            return -1.65 if word == 'from' else 0.3
        if re.search(r'\b\w+ed$', previous):
            return 0.10 if word == 'from' else 0.03
    if word == 'Topic' and previous.endswith('Author'):
        return -1.2
    if word in {'Topics', 'Threads', 'topics'} and previous.endswith('Similar'):
        return -0.4 if word == 'topics' else -1.7
    if word == 'Reputation' and previous.endswith('Posts'):
        return -0.7
    if word == 'Info' and previous.endswith('Tag'):
        return -6.0
    if word == 'INFO' and previous.endswith('DOCUMENT'):
        return -1.5
    if word == 'Presenter' and previous.endswith('Transcript and'):
        return -1.8
    if word == 'tagged' and previous.endswith('questions'):
        return -1.5
    if word.lower() == 'results' and previous.lower().endswith(('showing', 'search')):
        return -0.9
    if word == 'SOFTWARE' and previous.endswith('THIS'):
        return -0.75
    if word == 'filename' and (before == '<' or '<reponame>' in before):
        return 1.5
    return 0.0


