            value = -0.94
        elif previous in OTHER_PERSONAL:
            value = -0.77
        elif previous == 'its':
            value = -0.48
        elif previous in {"'s", '’s'}:
            value = -0.66
        elif previous == 'very':
            value = -0.24
        else:
            value = 0.0
        if before == 'on' and previous in PERSONAL | OTHER_PERSONAL:
            value += 0.27
        elif before == 'on' and previous == 'its':
            value += 0.12
    return (doc, word, previous), value

