READS = ()
PREPOSITIONS = frozenset(
    "of in to for from with by at as on into using".split()
)


def response(before, token, position):
    word = token.strip()
    lower = before.lower()

    # Structural punctuation, including runs at the very start of a document.
    if token == "://":
        return 0.21
    if (len(word) >= 6 and set(word) == {":"}
            and "/*" in before and ":::" in before):
        return -min(5.0, 0.63 * len(word))
    if token == "::":
        if before.endswith("Request"):
            return 0.85
        return -0.32 if before.endswith("std") else -0.08
    if len(token) > 1 and set(token) == {"·"}:
        return 0.35
    if token == "\r" and not before.strip("\r"):
        return -2.04
    if len(token) > 2 and set(token) == {"^"} and not before.strip("^"):
        return 1.74
    if position == 0 and token == "//\n":
        return -3.28
    if position == 1 and before == "1" and token == "2":
        return 2.85
    if position == 1 and before == "Title" and token == ":":
        return 1.38

    if position == 0:
        if word.lower() in PREPOSITIONS:
            return -0.33
        if word.lower() in {"a", "an"}:
            return 0.22
        if token and not token.strip(" "):
            return -0.22
        if word in {".", ":", "-"}:
            return -0.25
        if token in {"package", "#include"}:
            return 0.31

    # A spaced colon is especially distinctive in scraped headings and labels.
    if token.startswith(" :") and token.strip() == ":":
        if lower.endswith("last updated"):
            return -2.4
        if re.search(r"\bproblem\s+\d+$", lower):
            return -2.7
        if re.search(r"\bquestion\s+[a-z]*\d+$", lower):
            return -1.1
        if re.search(r"(?:^|\n)[# \t]*question$", lower):
            return -2.8
        if re.search(r"article\s+\d+$", lower):
            return -1.4
        if re.search(r"(?:^|\s|@)(?:author|name|description|created time|source|summary|"
                     r"explanation|solution|excerpt|page|output|last question)$", lower):
            return -0.85
        if lower.endswith("for") and token.endswith("\n\n"):
            return -1.4
        if lower.endswith("posted in"):
            return -1.25
        return 0.10
    if token == ":\n\n":
        if lower.endswith("rate this question"):
            return -0.95
        if re.search(r"question\s+\d+$", lower):
            return -0.9
        if before == "Q":
            return -0.47

    if token == " /" and re.search(r"\bPage\d+$", before):
        return -0.55
    if token == "_" and re.search(r"\bsec$", lower):
        return -0.1

    # Conventional credits, navigation headings, and status-message wording.
    if word == "Related" and before.rstrip().endswith("##"):
        return -0.65
    if token == " Stats" and lower.endswith("question"):
        return -0.9
    if token == " Test" and before.endswith("MCQ"):
        return -0.85
    if token == " Option" and before.endswith("Correct"):
        return -0.74
    if word in {"Resources", "Articles", "Videos"} and lower.endswith("related"):
        return -1.4
    if word == "ournals" and lower.endswith("similar j"):
        return -0.8
    if token == " by" and re.search(r"last (?:edited|modified)$", lower):
        return 1.05
    if token == " contributed" and lower.endswith("this code is"):
        return 1.47
    if token == " message":
        if re.search(r"(?:reading|see|embed) this$|note: this$", lower):
            return 1.0
        if lower.endswith("received this"):
            return 0.4
        if lower.endswith("wrote in"):
            return 1.7
        return -0.18
    if token == " file" and before.endswith("* This"):
        return 0.8
    if token == " option" and lower.endswith("the correct"):
        return -2.8
    if token == " tagged" and lower.endswith("questions"):
        return 1.7
    if token in {" above", " below"} and re.search(r"questions?$", lower):
        return 1.5
    if token == " from" and lower.endswith("following excerpt"):
        return 0.8
    if token == " of" and lower.endswith("download pdf"):
        return 1.5
    if token == " by" and lower.endswith("contributed"):
        return 0.4
    if token == "php" and before == "<?":
        return 0.77
    if token == "资讯" and before.endswith("相关"):
        return -2.5
    if token == "列表" and before.endswith("评论"):
        return 0.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, position = "", 0
    else:
        _, before, position = carry
    token = prefix.token_strings[-1]
    value = response(before, token, position)
    return (doc, (before + token)[-120:], position + 1), value

"""Approximate local constructions opening ranges, examples or alternatives.

The largest signal is on FROM after range/anything/everything and at
sentence boundaries. Smaller signals mark possible states (CAN BE),
negated states (IS NOT), MORE THAN, SUCH AS, and WHETHER alternatives.
Coefficients are training-set averages, not exact semantic judgments.
Only the recent text in the current document is retained; other tokens
receive a near-zero baseline. Much context-dependent variation is omitted.
"""
import re

READS = ()

COPULAS = {'is', 'are', 'am', 'was', 'were', "'s", '’s', "'re", '’re',
           "'m", '’m'}
POSSIBILITY = {
    'can': 1.071, 'could': 0.553, 'may': 0.335,
    'might': 0.371, 'cannot': 0.227, 'shall': 0.157,
}
RANGE = re.compile(r'\b(?:range[sd]?|ranging)(?:\s+\w+){0,5}[,;]?\s*$')
BREADTH = re.compile(r'\b(?:everything|anything|anywhere)[,;]?\s*$')
CHANGE = re.compile(r'\b(?:shift\w*|transition\w*|evolv\w*|extend\w*|'
                    r'span\w*|chang\w*|start\w*|begin\w*|began|move[sd]?)\b')


def response(s, context, previous):
    """Estimate strength from local grammatical constructions."""
    w = s.strip()
    lower = w.lower()
    p = previous.strip().lower()
    recent = context.lower()[-100:]
    if lower == 'from' and (s.startswith(' ') or w == 'From'):
        # Source-code identifiers and mathematical deductions are not ranges.
        if re.search(r'[=\\{}\[\]_<]|\bimport\b', recent[-45:]):
            return -0.047
        if p in {'range', 'ranges', 'ranging'}:
            if re.search(r'\b(?:the|a)\s+range\s*$', recent):
                return 3.298
            return 8.142
        if p in {'vary', 'varies', 'varied', 'varying'}:
            return 2.94
        if RANGE.search(recent[-65:]):
            return 8.012
        if BREADTH.search(recent[-45:]):
            return 9.874
        if p in {'–', '—', '--', '-'}:
            return 5.798
        if p in {',', ';'}:
            return 2.582
        if w == 'From' and context.endswith('\n\n'):
            return 0.544
        if w == 'From' and re.search(r'[.!?]["”\')]*\s*$', context):
            return 3.375
        if w == 'From' and (not context or context.endswith('\n')):
            return 1.396
        if CHANGE.search(recent[-40:]):
            return 0.405
        return -0.047
    if lower == 'whether':
        if p in {',', ';'}:
            return 2.115
        if w == 'Whether' and re.search(r'[.!?]["”\')]*\s*$', context):
            return 4.048
        return -0.108
    # WHETHER IT BE / WHETHER IT IS / WHETHER YOU ARE, etc.
    if re.search(r'\bwhether(?:\s+\w+){0,2}\s*$', recent):
        if lower in {'be', 'is', 'are', "'s", '’s'}:
            if re.search(r'\bwhether\s+(?:it|that|this|you)\s*$', recent):
                return 3.866
            return 0.627
        if lower in {'it', 'you', 'in'}:
            return 1.109
    if lower == 'be' and s.startswith(' '):
        if p in POSSIBILITY:
            return POSSIBILITY[p]
        return 0.055
    if lower == 'not' and s.startswith(' '):
        if p in COPULAS:
            return 0.496
        if p in {'has', 'have', 'had'}:
            return -0.248
        if p in {'do', 'did', 'does', 'but'}:
            return -0.1
        return 0.065
    if lower == 'than' and p == 'more':
        return 1.318
    if lower == 'as' and p == 'such':
        return 0.476
    if lower in {'include', 'includes', 'including', 'included'}:
        return 0.452
    if lower == 'ranging':
        return 1.794
    if lower == 'range' and p in {'can', 'could', 'may', 'which'}:
        return 1.663
    if lower == 'range' and p in {'a', 'wide', 'broad', 'diverse', 'full'}:
        return 0.881
    if lower == 'with' and p in {'filled', 'packed', 'complete', 'overflowing'}:
        return 1.052
    if lower == 'with' and p in {'start', 'starts', 'starting', 'started',
                                'begin', 'begins', 'beginning', 'began', 'end'}:
        return 0.595
    if lower == 'with' and p == ',':
        return 0.422
    if lower == 'of' and p in {'outside', 'full', 'likes'}:
        return 0.801
    if lower == 'to' and re.search(r'\bfrom\b', recent[-60:]):
        start = recent.split('from')[0]
        if RANGE.search(start) or BREADTH.search(start):
            return 1.026
        return 0.219
    # Spanish/Portuguese FROM; Chinese range and inclusion markers.
    if lower == 'desde':
        return 2.824
    if lower in {'从', '從', '从小', '從小', '由小', '到', '包括'}:
        return 0.789
    # Chinese WHETHER / REGARDLESS OF WHICH.
    if lower in {'不论是', '無論', '无论', '無論是', '无论是'}:
        return 2.347
    if lower == 'some' and w == 'Some':
        return 0.535
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        context, previous = '', ''
    else:
        _, context, previous = carry
    s = prefix.token_strings[-1]
    value = response(s, context, previous)
    return (doc, (context + s)[-160:], s), value

programs.haiku:
"""Layer-1 MLP component 4970: a "scope opener" detector.

It fires on the word that opens a span, a comparison, an alternative or an inclusion,
mostly where a reader would see a range or list being set up:
  - "from" that starts a range or list: "everything from X to Y", "ranging from X",
    "a wide range of clients from ..." (strongest); ", from ..." and a capitalised
    sentence-initial "From" (medium); lowercase sentence-initial "from" (a Python import)
    and any other "from" are silent;
  - "to" a few words after such a "from" (the close of "from X to Y");
  - "Whether" starting a sentence or clause ("Whether it be ...", "Whether you are ..."),
    and the word or two after it;
  - "than" after "more" ("more than just ..."), "beyond", "not only" / "not just";
  - "be" after a modal: "can be" (strong), "could be" / "may be" (weaker);
  - "such as", "including" / "include", and a faint "not".
Everything else is predicted as 0: the component is nearly silent there.
Values are rounded means of the component's activation for each pattern, fitted on
training rows; the program is a small rule table, not a model of the network.
"""

READS = ()

RANGE_NOW = {"everything", "anything", "range", "ranging", "ranged", "varies", "spans",
             "scale", "anywhere"}
RANGE_NEAR = {"ranges", "variety", "wide", "spectrum", "offering", "offers", "covering",
              "covers", "includes", "including", "range", "ranging", "all", "many",
              "everyone", "options", "types", "kinds", "levels", "topics", "issues",
              "products", "services", "sizes", "prices", "ages", "clients", "customers",
              "people"}
FROM_WORDS = {"from", "从", "от", "desde", "из"}
WHETHER_WORDS = {"whether", "ob", "无论是"}
SENTENCE_END = {"", ".", "?", "!", "\n", "。", "”", '"'}
COMMA_LIKE = {",", ";", "—", "–", "-", "--", ":", "：", "，"}
MODALS = {"could", "may", "might"}
INCLUDE_WORDS = {"including", "include", "includes", "included", "包括", "encompasses"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    n = len(toks)
    raw = toks[-1].strip()
    cur = raw.lower()

    def back(k):
        # The word k tokens back, or "" before the start of this document.
        if n > k and docs[-1 - k] == docs[-1]:
            return _word(toks[-1 - k])
        return ""

    prev, prev2 = back(1), back(2)
    near = {back(k) for k in range(1, 5)}  # the four words before this one

    value = 0.0
    if cur in FROM_WORDS:
        if prev in RANGE_NOW:
            value = 7.0
        elif near & RANGE_NEAR:
            value = 1.0
        elif prev in COMMA_LIKE:
            value = 2.4
        elif raw == "From" and prev in SENTENCE_END:
            value = 2.4
    elif cur == "to" and any(back(k) in FROM_WORDS for k in range(1, 6)):
        value = 0.4
    elif cur in WHETHER_WORDS and (prev in SENTENCE_END or prev in COMMA_LIKE):
        value = 1.7
    elif prev in WHETHER_WORDS or prev2 in WHETHER_WORDS:
        value = 0.2
    elif cur == "than" and prev == "more":
        value = 1.4
    elif cur == "be" and prev == "can":
        value = 1.1
    elif cur == "be" and prev in MODALS:
        value = 0.4
    elif cur == "beyond":
        value = 0.7
    elif cur in ("only", "just") and prev == "not":
        value = 1.1
    elif cur == "as" and prev == "such":
        value = 0.45
    elif cur in INCLUDE_WORDS:
        value = 0.45
    elif cur == "not":
        value = 0.15
    return carry, float(value)

"""layers.1.mlp.down_proj:4971 -- a "user-interface / browser front-end" feature.

What it does, in plain terms:
  * Goes negative on user-interface and browser front-end vocabulary: click and DOM-event
    calls (click, onClick, addEventListener, getElementById, preventDefault, jQuery $("#...)
    are the strongest; GUI-toolkit and UI nouns (Android, Swing/AWT, widget, button, view,
    render, React, window, form, menu) are moderate; HTML/JSX markup (<, =", div, span,
    class) is weak. The same UI ideas written in Chinese, Russian or Japanese count too.
  * Goes slightly positive on logging and plain C/Java plumbing (console.log, println,
    #include, namespace, .xml), and on the first token of each document.
  * Predicts 0 otherwise, which is where most tokens sit.
  * A run of middle-dot filler characters ("··") gets the fixed value seen in the data.

Levels are the mean activations observed for each group on training rows.
It explains only a few percent of the variance: the component is mostly small and diffuse,
and most of its large negative values sit on UI-code tokens, which this list captures.
"""
import re

READS = ()

EVENT_DOM = {"click", "clicked", "clicking", "onclick", "hover", "focus", "focused",
             "addeventlistener", "getelementbyid", "queryselector", "innerhtml", "settext",
             "preventdefault", "jquery", "dom", "listener", "event", "fireevent"}
GUI_WORDS = {"android", "awt", "swing", "widget", "layout", "button", "window", "render",
             "react", "view", "gui", "ui", "interface", "component", "screen", "form",
             "dialog", "menu", "modal", "label", "panel", "element", "page", "select",
             "selected", "submit", "show", "controls", "design", "editor"}
MARKUP = {"div", "span", "td", "br", "class", "href", "img", "align", "height", "margin",
          "css", "html", "style"}
PLUMBING = {"log", "console", "println", "include", "namespace", "xml", "print"}
UI_OTHER_LANGS = ("点击", "界面", "页面", "元素", "选择", "事件", "按钮", "кноп", "элемент",
                  "выб", "動", "キー", "鼠标")


def words(token):
    """Lower-case words of a token, camelCase split: '.addEventListener' -> add, event, listener."""
    return set(w.lower() for w in re.findall(r"[A-Z]+(?![a-z])|[A-Z]?[a-z]+", token))


def value(token):
    """The activation this one token's text predicts, outside document starts."""
    if token == "··":
        return 0.74
    if "$(" in token or any(s in token for s in UI_OTHER_LANGS):
        return -0.6
    w = words(token)
    if w & EVENT_DOM:
        return -0.6
    if w & GUI_WORDS:
        return -0.3
    if w & MARKUP or token.strip() in ("<", '="', "={", '("'):
        return -0.2
    if w & PLUMBING:
        return 0.12
    return 0.0


def step(carry, prefix, upstream):
    """Called once per token. The first token of a document gets +0.16; otherwise the
    value comes from the token's own text (no state is carried)."""
    new_doc = len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        return carry, 0.16
    return carry, value(prefix.token_strings[-1])

"""The component is a 'function' detector. It goes negative on the word 'function'
(in any language, or fn/func names, as in "a function" or "Function"), and on the
function-notation f(x) (a letter naming a function, then its argument). It is about
zero for code keywords ("public function") and turns positive in the role sense
("the function of", "its function")."""
import re
FUNCTION_WORDS = {"function", "functions", "func", "fn", "funk", "funktion", "funktionen",
                  "fonction", "función", "funciones", "funcion", "функция", "функции",
                  "функцию", "функци", "função", "hàm", "函数", "функ"}
ARTICLES = {"a", "an", "the", "this", "that", "each", "every", "another", "helper", "recursive"}
ROLE_WORDS = {"its", "their", "his", "her", "to", "and"}
CODE_KEYWORDS = {"public", "private", "protected", "static", "async", "export"}
CURRENT = re.compile(r"([^\W\d_]+)$")
PREVIOUS = re.compile(r"([^\W\d_]+)\W*$")
ARG = re.compile(r"(?<![^\W\d_])[a-zA-Z]\(x$")      # f(x
NAME = re.compile(r"(?<![^\W\d_])[fgh]\($")         # f(
READS = ()

def is_function_word(word):
    return word in FUNCTION_WORDS or word.endswith(("function", "func", "fn"))

def step(carry, prefix, upstream):
    text = prefix.text_prefixes[-1][-80:]
    if ARG.search(text):
        return None, -1.5
    if NAME.search(text):
        return None, -0.7
    m = CURRENT.search(text)
    if m is None:
        return None, 0.0          # the token does not end a word
    word = m.group(1)
    before = text[:m.start()]
    pm = PREVIOUS.search(before)
    prev = pm.group(1).lower() if pm else ""
    if is_function_word(word.lower()):
        if word[0].isupper() or not word.isascii():
            return None, -2.8     # capitalised identifiers and foreign words
        if prev in CODE_KEYWORDS or before.rstrip().endswith(("=", ":")):
            return None, -0.4     # code keyword use, e.g. "public function"
        if prev in ARTICLES:
            return None, -2.8     # "a function", "the function"
        if prev in ROLE_WORDS:
            return None, 1.0      # role sense, "its function"
        return None, -1.5
    if prev and is_function_word(prev.lower()):
        if word == "of":
            return None, 1.6      # "the function of ..."
        if word in ("to", "that"):
            return None, -1.2
    return None, 0.0

programs.sol:
"""A sparse lexical approximation, not a general semantic detector.

The main negative responses are repeated middle dots, Greek eta after
consonants (especially dentals), and individual Han characters whose primary
meanings are mud, pool, doubt, congealing, or stickiness. Mud also carries
through short compounds. Document beginnings have a small negative offset,
stronger for function/class declarations and the document-end marker.
Byte-fragment spikes, positive Han spikes, and ordinary context variation
are omitted to keep the approximation short.
"""
from functools import lru_cache
import regex
import unihan

READS = ()

# Classes are identified by the primary English meaning in Unicode's table.
HAN_MEANINGS = (
    ('mud', -5.0),
    ('pool', -3.0),
    ('doubt', -4.0),
    ('coagulate', -3.3),
    ('viscous', -1.7),
)


@lru_cache(maxsize=8192)
def han_response(text):
    if not regex.fullmatch(r'\p{Script=Han}{1,2}', text):
        return None
    if len(text) == 1:
        meaning = unihan.definition(text) or ''
        for concept, value in HAN_MEANINGS:
            if meaning.startswith(concept):
                return value
    elif any((unihan.definition(c) or '').startswith('mud') for c in text):
        return -2.5
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = b'' if first else carry[1]
    text = prefix.token_strings[-1]
    word = text.strip()
    value = -0.10 if first else 0.002

    if first and word in {'def', 'class', 'function'}:
        value = -2.0
    if first and word == '<|endoftext|>':
        value = -2.93
    if len(word) >= 2 and set(word) == {'·'}:
        value = -3.43
    elif word == 'η':
        previous = tail.decode('utf-8', errors='ignore')[-1:].lower()
        if previous in {'τ', 'δ', 'θ'}:
            value = -1.75
        elif previous in {'σ', 'ς', 'ξ', 'ψ', 'ζ'}:
            value = 0.05
        elif previous and previous in 'αεηιουω':
            value = -0.4
        elif previous and regex.fullmatch(r'\p{Script=Greek}', previous):
            value = -0.95
        else:
            value = 0.03
    else:
        han = han_response(word)
        if han is not None:
            value = han

    tail = (tail + prefix.token_bytes[-1])[-24:]
    return (doc, tail), value

"""Approximate a signed y--vowel transition detector.

Look for y followed by a vowel in a short word fragment, including transitions
split over tokens. Vowel+y gives a negative response, consonant+y a positive
one (strongest before o). Longer fragments generally weaken the response.
Ignore a capital letter after lowercase, as in camelCase identifiers.
There is also a small negative start bias and a separate middle-dot repeat
response. Accents are ignored; no word or token-ID lookup table is used.
"""
import unicodedata

READS = ()
VOWELS = 'aeiou'
CONSONANTS = 'bcdfghjklmnpqrstvwxz'


def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def transition(before, after, word_length, length, previous, y_here):
    if before in VOWELS and before:
        if before == 'a':
            if after == 'i':
                return 0.0
            return -0.7 if after == 'e' else -2.7
        if y_here:
            return -0.2
        return -3.0 if after == 'u' else -1.0
    if not before or before not in CONSONANTS:
        return 0.0
    if after == 'o':
        if len(previous.strip()) > 3:
            return 0.5
        if length <= 2:
            return 5.7 if previous[:1].isspace() else 3.6
        return 2.3
    if word_length <= 1:
        return 2.3 if length <= 3 else 0.0
    if before in 'fhsvz':
        return 2.4 if length <= 2 else -0.1
    return 0.35


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev2 = prev = prev_raw = ''
    else:
        _, prev2, prev, prev_raw = carry
    raw = prefix.token_strings[-1]
    token = plain(raw)
    state = (doc, prev, token, raw)
    value = 0.0
    if not prev or prev_raw == '<|endoftext|>':
        if raw.strip().isdigit():
            value = -0.5
        elif raw.strip() and not any(c.isalnum() for c in raw):
            value = -0.4
        else:
            value = -0.23
    if token and set(token) == {'·'} and len(token) >= 2 and prev.endswith('·'):
        return state, -3.1
    text = prev2 + prev + token
    start = len(prev2) + len(prev)
    y = text.rfind('y', max(0, start - 3))
    if (y >= 0 and y + 1 < len(text) and y < start + 2
            and text[y + 1] in VOWELS and token[:1].isalpha()
            and not (raw[:1].isupper() and prev_raw[-1:].islower())
            and (y >= start or all(c in VOWELS for c in text[y + 1:start + 1]))):
        before = text[y - 1:y] if y else ''
        before_y = text[:y]
        word_length = len(before_y) - len(before_y.rstrip(CONSONANTS + VOWELS))
        value = transition(before, text[y + 1], word_length,
                           len(token), prev, y >= start)
    return state, value

"""Chat boundaries and pictorial Unicode symbols give negative pulses.

Message endings are weaker after tools, and depend on the visible speaker
and whether an earlier message has ended. Emoji are strong; familiar printed
symbols are weaker. Unfinished UTF-8 characters are carried across tokens,
so fragments of an emoji respond too. Emoji presentation selectors have
an intermediate negative response. Most ordinary text returns zero.
Some protocol openers and doubled middle dots give positive pulses.
"""
import codecs
from functools import lru_cache
import regex

READS = ()
EMOJI = regex.compile(r'\p{Emoji_Presentation}')
PICTURE = regex.compile(r'\p{Extended_Pictographic}')
FLAGS = regex.compile(r'\p{Regional_Indicator}')
SKIN = regex.compile(r'\p{Emoji_Modifier}')


@lru_cache(maxsize=50000)
def graphic(pending, token):
    decoder = codecs.getincrementaldecoder('utf8')('replace')
    decoder.setstate((pending, 0))
    text = decoder.decode(token)
    tail = decoder.getstate()[0]
    joined = pending + token
    if '\ufe0f' in text:  # emoji presentation selector
        value = -6.1
    elif b'\xf0\x9f' in joined:  # supplementary pictographic range
        if FLAGS.search(text):
            value = -4.7
        elif SKIN.search(text):
            value = -3.9
        elif pending:
            value = -10.5
        elif tail:
            value = -7.8
        elif token.startswith(b' '):
            value = -3.7
        else:
            value = -10.0
    elif EMOJI.search(text):
        if pending:
            value = -12.1
        elif '✅' in text:
            value = -5.6
        elif '❌' in text:
            value = -7.7
        else:
            value = -6.6
    elif PICTURE.search(text):
        if pending:
            value = -6.4
        elif any(c in text for c in '©®™'):
            value = -0.3
        elif '✝' in text:
            value = -0.9
        elif '✔' in text:
            value = -2.4
        elif any(c in text for c in '♥♦♠♣') or '➡' in text:
            value = -2.4
        else:
            value = -5.5
    elif tail.startswith(b'\xe2'):
        # Two UTF-8 bytes can already locate a family of symbols.
        value = {
            b'\xe2\x98': -4.3,  # weather signs and faces
            b'\xe2\x99': -0.7,  # music, gender and card symbols
            b'\xe2\x9a': -2.5,  # dice and miscellaneous pictographs
            b'\xe2\x9c': -3.3,  # scissors, ticks and other dingbats
            b'\xe2\x9d': -1.6,  # ornamental dingbats and hearts
            b'\xe2\xa0': -1.8,  # braille patterns
        }.get(tail, 0.0)
        if tail == b'\xe2' and token.startswith(b' '):
            value = -1.1
    elif any(c in text for c in '✓✗'):
        value = -0.9
    elif any(c in text for c in '〜～☆♪'):
        value = -1.1
    elif regex.search(r'\p{Block=Geometric_Shapes}', text):
        value = -0.5
    else:
        value = 0.0
    return tail, value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '', '', '', 0)
    _, pending, role, tag, last, endings = carry
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    if last == '<|im_start|>':
        role = token
    if token == '<|im_start|>':
        role, tag = '', ''
    if token in ('</tool_call>', '</tool_response>'):
        tag = token
    if raw.isascii():
        pending, value = b'', 0.0
    else:
        pending, value = graphic(pending, raw)
    if token == '<|im_end|>':
        if tag == '</tool_call>':
            value = -1.05 if role else -1.46
        elif tag == '</tool_response>':
            value = -1.88 if role else -2.10
        elif role == 'user':
            value = -3.79 if endings == 0 else -2.77
        else:
            value = -3.05 if role else -3.51
        endings += 1
    elif token == '</think>':
        value = -4.83
    elif token == '<tool_call>':
        value = -1.30
    elif token == '<|im_start|>':
        value = 0.22
    elif token == '<think>':
        value = -0.24
    elif token in ('</tool_call>', '<tool_response>'):
        value = 0.13
    elif token == '··':
        value = 1.60
    return (doc, pending, role, tag, token, endings), value

