"""Layer-1 MLP down-projection unit 4978: a negative "end of turn / emoji" detector.

The unit is almost silent on ordinary text. It turns strongly negative on a few
kinds of token:

- the chat end-of-turn token <|im_end|> (moderately negative after prose, weaker
  right after a tool-call or tool-response block);
- the close of a reasoning block </think> (strongly negative);
- the tool-call opener <tool_call> (mildly negative);
- pictographic symbols: emoji (strongest), and dingbat-style marks such as check,
  cross, warning and heart signs (moderate), plus the emoji variation selector U+FE0F.

Everything else is predicted as 0. The values are rough per-token averages read off
training text, not fitted parameters.
"""

import unicodedata

READS = ()

END_OF_TOOL_BLOCK = ("</tool_response>", "</tool_call>")


def _symbols(text):
    """Symbol characters (Unicode So/Sk, from U+2100 up) in a token, excluding U+FFFD."""
    return [
        ch
        for ch in text
        if ch != "�" and unicodedata.category(ch) in ("So", "Sk") and ord(ch) >= 0x2100
    ]


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2] if same_doc else ""

    if tok == "<|im_end|>":
        return carry, (-1.5 if before in END_OF_TOOL_BLOCK else -3.0)
    if tok == "</think>":
        return carry, -4.8
    if tok == "<tool_call>":
        return carry, -1.3
    if tok == "️":
        return carry, -5.0
    symbols = _symbols(tok)
    if symbols:
        if any(ord(ch) >= 0x1F000 for ch in symbols):
            return carry, -7.0
        return carry, -1.5
    return carry, 0.0

