"""Detect m-(optional vowels)-r fragments, including across token edges.

The negative response is strongest for 'mer'. Short fragments and newly
completed syllables respond more than long familiar words. Transliteration
lets the same spelling rule cover other scripts. This is a fragment detector,
not a semantic rule about all words containing those letters.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
PATTERN = re.compile(r'm([aeiouy]{0,3})r')

@lru_cache(maxsize=8192)
def spelling(token):
    return anyascii(token).lower()

@lru_cache(maxsize=8192)
def frequency(word):
    return zipf_frequency(word, 'en')


def response(previous, token, previous_token=''):
    text = previous[-6:] + token
    boundary = len(previous[-6:])
    word = token.strip()
    value = 0.0
    for match in PATTERN.finditer(text):
        if match.end() <= boundary:
            continue
        vowel = match.group(1)
        suffix = len(text) - match.end()
        cross = match.start() < boundary
        space = bool(token and token[0].isspace())
        if len(word) <= 3:
            if vowel == 'e':
                strength = 4.2
                if cross and token.startswith('er'):
                    strength = 6.0 if len(previous_token.strip()) <= 4 else 2.5
            elif vowel == 'a':
                strength = 3.6 if cross else (1.1 if space else 2.0)
                if cross and token.startswith('arr'):
                    strength *= 1.5
            elif vowel == 'i':
                strength = 2.7 if cross else 0.8
            elif not vowel:
                strength = 2.0
            else:
                strength = 1.5 if 'e' in vowel else 0.6
        elif cross:
            # A new token completes a spelling begun in the preceding token.
            strength = 3.0 if vowel == 'e' else 0.9
            if suffix >= 3:
                strength *= 0.1
            if len(previous_token.strip()) > 4:
                strength *= 0.3
        else:
            start = match.start() - boundary
            before_m = token[:start].strip()
            short_stem = bool(re.fullmatch(r'[aeiou]?m?', before_m))
            # Short vowel prefixes expose fragments such as imer and omer.
            if short_stem and word.endswith('r') and len(word) <= 5:
                strength = 5.0 if vowel == 'e' else 3.2
                if 'mm' in word:
                    strength *= 0.55
                if space:
                    strength *= 0.65
            elif frequency(word) > 3:
                strength = 0.12
            elif len(word) > 6:
                strength = 0.03
            elif short_stem and vowel == 'e' and suffix <= 2:
                strength = 3.5 if not space else 0.7
            else:
                strength = 1.5 if suffix == 0 else 0.3
        if len(vowel) > 1:
            strength *= 0.3
        value = min(value, -strength)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    # Never join spelling across a document boundary.
    tail, previous = carry[1:] if carry and carry[0] == doc else ('', '')
    token = spelling(prefix.token_strings[-1])
    value = response(tail, token, previous)
    return (doc, (tail + token)[-6:], token), value

