"""layers.1.mlp.down_proj:4981 -- a placeholder-address / web-address detector.

What it does: this component goes strongly negative on the pieces of placeholder or
obfuscated e-mail addresses, and mildly negative on the names of web hosts and URL
paths (GitHub, YouTube, /blob, ...). Almost everywhere else it is near zero. The big
negative spikes are on

  firstname | .lastname | @example .org/.com   (the example address firstname.lastname@example.org)
  [email protected]                            (Cloudflare-obfuscated address)

and it is slightly positive at the end of an assistant turn (<|im_end|>).

This program predicts those values from the tokens seen so far (a row's document
boundary resets the context):
  - placeholder address: "firstname" -> -7; ".lastname" right after it -> -24;
    "@example" -> -18 right after "email" or ".lastname", otherwise -10 (e.g. in code);
    ".example" -> -4; "email" right after "[" -> -10 (obfuscated), other "email" -> -2;
    " protected" right after "email" -> -4.5.
  - URL pieces: "/blob" -> -11, "/tree" -> -5, other path words (/watch, /issues,
    /channel, /profile) -> -1.2 to -2; tokens containing "github" -> -2.4; website names
    (.youtube, .twitter, .imgur, .blogspot, .wikipedia, .google, ...) -> -2.5;
    runs of "____" or "====" -> -1.5.
  - "<|im_end|>" -> +0.6.
  - everything else -> 0.
"""

READS = ()

URL_PATHS = {"/blob": -11.0, "/tree": -5.0, "/watch": -2.0, "/issues": -1.5,
             "/channel": -1.2, "/profile": -1.3}
SITE_PIECES = {".youtube", ".twitter", ".imgur", ".blogspot", ".wikipedia", ".google",
               ".co", ".post", ".archive", ".githubusercontent"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = toks[-1]
    same_doc = len(toks) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = toks[-2].strip() if same_doc else ""
    if t == "@example":
        return None, -18.0 if prev in ("email", ".lastname") else -10.0
    if t == ".lastname" and prev == "firstname":
        return None, -24.0
    if t.strip() == "firstname":
        return None, -7.0
    if t == "email":
        return None, -10.0 if toks[-2:-1] == ["["] else -2.2
    if t == " protected" and prev == "email":
        return None, -4.5
    if t == ".example":
        return None, -3.8
    if t in URL_PATHS:
        return None, URL_PATHS[t]
    if "github" in t.lower():
        return None, -2.4
    if t in SITE_PIECES:
        return None, -2.5
    if t.strip("_") == "" and len(t) >= 4:
        return None, -1.5
    if t == "<|im_end|>":
        return None, 0.6
    return None, 0.0

