"""Sparse spelling rules, not a general semantic classifier.

The largest positive responses are German ge-/zu- word fragments and a few
Thai and Korean consonant/ending spellings.  Negative responses concentrate
on ka-w/ka-mp spellings and Japanese kawa.  Most tokens receive zero.
Only a short text tail and a fading German-function-word count are retained.
Token boundaries matter: this does not classify every word with these sounds.
Double middle dots get a negative value; weaker lexical responses are omitted.
"""
import re
import unicodedata

READS = ()
GERMAN_FUNCTION_WORDS = frozenset('''
der die das den dem des ein eine einer einem einen eines und nicht ist sind
war wird werden wurde auch sich mit von für auf aus bei nach über zur zum
aber noch nur oder als wenn schon durch seine ihre im dass daß
'''.split())
SEPARABLE = re.compile(
    r'(?:^|\W)(?:ab|an|auf|aus|bei|durch|ein|entgegen|fort|her|hin|los|mit|nach|'
    r'nieder|über|um|unter|vor|weg|weiter|wieder|zu|zurück|zusammen|heraus|hinzu|'
    r'teil|hoch|fest|hinweg|wahr)$', re.I)
PARTICIPLE = re.compile(r'ge[bcdfghjklmnpqrstvwxyz]{0,3}$')


def is_korean_syllable(ch):
    return unicodedata.name(ch, '').startswith('HANGUL SYLLABLE ')


def response(s, tail, german):
    t = s.strip()
    # Thai ko kai, its continuations, and cho chan.
    if t == 'ก':
        return 5.01 if s != t else 7.99
    if t in ('กร', 'กล', 'กว', 'กก'):
        return 2.92
    if (tail.endswith('ก') and s and unicodedata.category(s[0]) == 'Mn'
            and 'THAI' in unicodedata.name(s[0], '')):
        return 8.70 if s == 'ัน' else 2.50
    if t == 'จ':
        return 1.78
