    if t in ('하기', '하지'):
        if tail and is_korean_syllable(tail[-1]):
            return 8.69
        return 5.14
    if t in ('기', '지'):
        if s == t and tail and is_korean_syllable(tail[-1]):
            letters = unicodedata.normalize('NFD', tail[-1])
            # No final consonant, or the past-tense final consonant ss.
            if len(letters) == 2 or letters[-1] == 'ᆻ':
                return 4.44
        return 1.23
    if re.fullmatch(r'(?:긴|길|진|질|[기지](?:는|가|를|에|도|고))', t):
        return 1.88
    if re.fullmatch(r'(?:되|있|보)[기지]', t):
        return 4.00
    # Japanese kawa and ka- continuations in several spellings.
    if t == '川':
        return -2.46
    if tail.endswith(('か', 'カ')):
        if t in ('わ', 'ワ', 'わり'):
            return -4.41
        if t in ('い', 'イ'):
            return -1.53
    if s and not s[0].isspace() and tail.lower().endswith(('k', 'g', 'к')):
        labial = re.fullmatch(r'(?:aw\w*|ав\w*)', s, re.I)
        kamp = tail.lower().endswith('k') and re.fullmatch(r'amp\w*', s, re.I)
