                return 10.87
            return 3.52
        if s in ('zu', 'uz', 'zug'):
            return 5.50
        if s == 'ge':
            return 6.72
        if PARTICIPLE.fullmatch(s):
            return 3.52
    if t == 'gew' or t == 'ges' and (s != t or german):
        return 3.04
    if t == 'gesch':
        return 2.10
    if german and PARTICIPLE.fullmatch(t):
        return 1.82 if t == 'ge' else 0.47
    if t in ('ange', 'ausge') and (s != t or german):
        return 2.01
    if t in ('anz', 'einz') and s != t:
        return 5.09
    if t == 'ganz':
        return 3.34
    if t == 'kurz':
        return 2.31
    if german and t == 'z':
        return 1.48
    if s == '··':
        return -1.79
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, german_score = '', 0.0
    else:
        _, tail, german_score = carry
    s = prefix.token_strings[-1]
    value = response(s, tail, german_score > 0.8)
    german_score *= 0.95
    german_score += s.strip().lower() in GERMAN_FUNCTION_WORDS
    carry = doc, (tail + s)[-64:], german_score
    return carry, value

"""Approximate sequence-start and line-ending responses.

Initial tokens (including an uninterrupted initial repetition) get a negative
shape-dependent baseline. Later responses are mostly small. Exceptions include
newlines closing LaTeX environment openings, escaped line breaks, and Markdown
hard breaks. Ordinary newlines depend on the preceding character and whether
line breaks have already appeared. This omits token-specific lexical variation.
"""
import re

READS = ()
MATH_OPEN = re.compile(
    r'\\begin\{(aligned|align|alignedat|equation|eqnarray|array|'
    r'gather|gathered|multline|split)\*?\}\r?\n$'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True, '', '', 0, {})
    _, first, initial, previous, tail, lines, seen = carry
    initial = initial and token == first
    repetitions = seen.get(token, 0)
    last = previous[-1:]

    if initial:
        word = s.strip()
        letters = sum(c.isalpha() for c in s)
        if word.istitle() and s.isascii():
            if s.startswith(' '):
                value = -0.19 if letters > 1 else -0.02
            else:
                value = -0.39 if letters > 1 else -0.26
        elif letters > 1:
            value = -0.24
        else:
            value = -0.09 if len(s) <= 11 else -0.22
    elif '\n' in s:
        opening = MATH_OPEN.search(tail + s)
        if opening:
            value = 0.66 if opening[1] == 'aligned' else 0.44
        elif s in ('\\\n', '\\\r\n') and last in ('.', '$', '}'):
            value = 0.55
        elif s in ('  \n', '  \r\n'):
            if last.isspace():
                value = -0.10
            else:
                value = 0.14 / (1 + repetitions) ** 2
        elif s in (']\n', ']\r\n') and last == '\\':
            value = 0.34
        elif s == '\n':
            if last.isdigit():
                value = 0.13 if lines < 2 else 0.05
            elif last == '\\':
                value = 0.22
            elif last.isalpha() and lines < 2 and repetitions == 0:
                value = 0.06
            else:
                value = 0.004
        elif s.count('\n') > 1:
            value = -0.004
        elif last.isdigit():
            value = 0.03
        else:
            value = 0.01
    elif '\n' in previous:
        value = 0.012 if any(c.isdigit() for c in s) else -0.008
    elif last == ';':
        value = -0.024
    elif s.strip().isupper():
        value = -0.006
    elif '\\' in s or any(c in s for c in "\"'`"):
        value = -0.015
    elif '\ufffd' in s:
        value = -0.02
    else:
        value = 0.0

    if '\n' in s:
        seen[token] = repetitions + 1
        lines += 1
    carry = (doc, first, initial, s, (tail + s)[-100:], lines, seen)
    return carry, float(value)

programs.haiku:
"""Negation and inability, as the component reads them.

The component switches on in text that says something is NOT the case or NOT possible.
It reads three kinds of trigger word:
- negations: "not", "n't", "no", "never", "none", "nothing", "cannot" (and "pas", "nicht",
  "не", "没", "不能" in other languages); strongest when right after an auxiliary or "but"
  ("is not", "did not", "but not");
- words of inability or difficulty: "unable", "impossible", "unclear", "hard", "invalid";
- verbs of failure or ability: "failed", "refused", "seem", "possible", "able".

The word right after a trigger carries the signal on: strongest for "to", "any", "of",
"from" and "'t" ("unable [to]", "does not have [any]"), weaker for other words, and fading
over the next two or three tokens. Everything else is near zero.

Each step: the carry is the position of the last trigger word in this document (None if
there is none, or after a document break). The values are typical activations on these
words, scaled by 0.8, which fits the activations best.
"""

READS = ()

NEGATION = {"not", "n't", "’t", "'t", "nt", "no", "never", "none", "nothing", "neither",
            "nor", "cannot", "nobody", "nowhere"}
INABILITY = {"unable", "impossible", "unlikely", "unclear", "unknown", "uncertain", "rarely",
             "difficult", "hard", "challenging", "complicated", "tough", "insufficient",
             "undefined", "unresolved", "unanswered", "invalid", "useless", "ineffective"}
FOREIGN = {"pas", "nicht", "nie", "keine", "не", "ni", "não", "nem", "没", "没有", "无法",
           "不能", "不是", "并不", "尚未", "無", "未", "không", "non"}
BOOSTERS = {"am", "is", "are", "was", "were", "do", "does", "did", "has", "have", "had",
             "will", "would", "can", "could", "may", "might", "must", "should", "'m", "'s",
             "'re", "’s", "’re", "still", "but"}
PRECURSORS = {"failed", "failing", "failure", "refused", "seem", "possible", "able", "fail"}
FOLLOWERS = {"to", "'t", "’t", "any", "anything", "of", "from"}


def step(carry, prefix, upstream):
    t = prefix.position
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if t > 0 else ""
    last = carry
    if t > 0 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        last = None
    if word in NEGATION:
        return t, (2.6 if before in BOOSTERS else 0.8)
    if word in INABILITY or word in FOREIGN:
        return t, 1.6
    if word in PRECURSORS:
        return t, 0.8
    if last is None:
        return None, 0.0
    gap = t - last
    if gap == 1:
        return last, (2.4 if word in FOLLOWERS else 0.4)
    if gap == 2:
        return last, 0.32
    if gap == 3:
        return last, 0.12
    return last, 0.0

programs.sol:
"""Local source-code openings, especially import lists and destructuring braces.

The strongest response is the brace after JavaScript/TypeScript `import`.
Other declaration braces and import syntaxes have smaller responses.  A few
weaker rules recognize include paths, template parameters, and object receivers.
Indentation, real or escaped line breaks, and document starts change its size.
The predictor keeps only a short text suffix, resetting at document boundaries;
it does not parse or execute code.  Unrecognized positions receive zero.
"""
import re

READS = ()


def activation(s, prev, tail, position):
    p, w = prev.strip(), s.strip()
    context = tail.replace('\\n', '\n')
    keyword = p.lstrip('+-')  # diff hunks also contain import declarations
    brace = s in {' {', ' {\n', ' {\n\n', ' {\\', '{'}
    if brace:
        value = 0.0
        if keyword == 'import':
            value = 35.0 if position == 1 and prev == 'import' else (
                20.6 if prev.startswith('\t') else 24.0)
            if tail.endswith('\\nimport'):
                value = 19.5
        elif keyword == 'export':
            value = 11.0
        elif keyword == 'type' and re.search(r'\bimport\s+type$', context):
            value = 22.5
        elif keyword in {'const', 'let', 'var'}:
            # A C++ const-qualified method is not a destructuring declaration.
            if not re.search(r'\)\s+const$', context):
                value = 6.0
                if keyword == 'const':
                    value = 16.3 if prev == 'const' else 10.5
                    if tail.endswith('\\nconst'):
                        value = 13.5
                if s == '{':
                    value = 9.2
        elif p == ',' and re.search(r'\bimport\s+[\w$]+,\s*$', context):
            value = 11.0
        if '\n' in s:
            value *= 0.69
        elif '\\' in s:
            value *= 0.5
        return value

    if keyword == 'import':
        from_import = bool(re.search(r'\bfrom\b[^\n;]*$', context))
        if s in {' *', ' *\n'}:
            return 1.9 if from_import else (
                5.5 if prev.startswith('\t') else 7.0)
        if s.startswith(' ('):
            if '\\' in s:
                return 2.8
            return 5.0 if prev.startswith('\t') else (
                3.6 if prev.startswith(' ') else 6.8)
    if s == ' import' and re.search(r'\bfrom\b[^\n;]*$', context):
        return 2.8 if p == 'typing' else 1.4
    if p.endswith('include') and w in {'<', '"'}:
        return 1.3 if w == '<' else 1.7
    if w == 'typename' and '<' in prev:
        return 2.0
    if s == ' const' and keyword == 'export':
        return 3.3

    if w in {'self', 'this'}:
        if prev.isspace() or s.startswith('\t'):
            return 0.85 if w == 'self' else 1.35
        if w == 'self' and p in {'return', '=', 'if', 'in', 'await'}:
            return 0.6
        if w == 'this' and p in {'return', '=', 'await'}:
            return 1.2
    if s == '(self':
        return 0.16
    if s == '(this':
        return 0.82
    if s == '->' and p.endswith('this'):
        return 1.35
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, tail, position = '', '', 0
    else:
        _, prev, tail, position = carry
    s = prefix.token_strings[-1]
    value = activation(s, prev, tail, position)
    return (doc, s, (tail + s)[-100:], position + 1), float(value)

programs.haiku:
"""Module import/export statements: the token that opens what a statement imports or exports.

The component is a "module-import" feature. It is silent on almost all text and fires on:
  - the opening token of a JavaScript/TypeScript `import {` or `export {`   (strongest, ~20-25)
  - `const {` destructuring                                                   (~10)
  - the `*` of `import * as x` and the `(` of a Go `import (` block            (~4)
  - `export const`                                                            (~3)
  - the `import` keyword in the middle of a line, as in `from typing import`  (~1)
  - the `"` or `<` of `#include`                                              (~1.5)
  - the `esModule` flag of TypeScript's CommonJS output                       (~3)
and it takes a constant negative value (-2.6) on runs of middle dots (·), a degenerate filler.
Everything else predicts 0. Values are typical activations read off training text.
"""

READS = ()

OPEN_VALUE = {"{": 22.0, "*": 4.0, "(": 4.5, "const": 3.0}


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev, raw = "", prefix.token_strings[-1]
    else:
        prev, raw = prefix.token_strings[-2].strip(), prefix.token_strings[-1]
    cur = raw.strip()
    value = 0.0
    if cur and set(cur) == {"·"}:
        value = -2.6
    elif prev in ("import", "export"):
        for mark, v in OPEN_VALUE.items():
            if cur.startswith(mark):
                value = v
                break
    elif prev == "const" and cur.startswith("{"):
        value = 10.0
    elif prev == "#include" and cur[:1] in ('"', "<"):
        value = 1.5
    elif cur == "esModule":
        value = 3.0
    elif raw == " import":
        value = 1.2
    return carry, value

programs.sol:
"""Split negative prefixes and short negation/qualification constructions.

An attached continuation of un-/non- gets a negative signal, strongest for
unfamiliar combinations. Familiar whole words, longer stems, single
letters, and lexicalized non-negative families weaken it. A few ordinary
English qualification phrases get a positive signal. Other tokens get zero.
The carry stores only the current word and a short preceding text window.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
# These families begin with the same letters without being productive negation.
LEXICALIZED = ('univ', 'unio', 'unit', 'uniq', 'unif', 'under',
               'until', 'unto', 'uncle', 'nonetheless')
TAIL = re.compile(r'[^\W\d_]+(?:-[^\W\d_]*)*$')
CAMEL = re.compile(r'(?:[A-Z][a-z]*|[A-Z]+)$')
# (rarity cutoff, stem-length decay, single-letter discount,
#  lexical-family discount, base strength, root-frequency strength)
PARAMS = {
    'un': (4.0, 0.1, 0.6, 0.5, 0.246, 0.171),
    'non': (3.5, 0.6, 1.0, 0.0, 0.275, 0.048),
}

@lru_cache(maxsize=32768)
def morphology(previous, token):
    if not token or not (token[0].isalpha() or token[0] == '-'):
        return None
    m = CAMEL.search(previous)
    previous = m[0] if m else previous
    previous = previous.lower().replace('-', '')
    if not previous.isascii():
        return None
    kind = 'un' if previous.startswith('un') else 'non'
    if not previous.startswith(kind):
        return None
    m = re.match(r'[a-zA-Z]+', token.lstrip('-'))
    if not m:
        return None
    letters = m[0].lower()
    whole = previous + letters
    return (kind, len(previous) - len(kind), len(letters),
            zipf_frequency(whole, 'en'),
            zipf_frequency(whole[len(kind):], 'en'),
            whole.startswith(LEXICALIZED))


def qualification(history, token):
    word = token.strip().lower()
    if not word.isalpha():
        return 0.0
    words = re.findall(r"[a-z]+(?:['’][a-z]+)?", history.lower())[-5:]
    last = words[-1] if words else ''
    neg = last == 'not' or last.endswith(("n't", 'n’t'))
    if neg:
        if word in ('saying', 'suggesting'):
            return 3.9
        if word in ('say', 'mean', 'suggest', 'imply', 'indicate'):
            return 1.4
        if word in ('sure', 'certain', 'convinced'):
            return 1.2
        if word == 'exactly':
            return 2.1
        if word == 'that':
            return 1.0
        if word in ('so', 'very', 'much', 'everyone'):
            return 0.73
    if last == 'to' and len(words) > 1 and words[-2] == 'not':
        if word == 'say':
            return 7.0
    if last == 'no' and word == 'means':
        return 5.75 if len(words) > 1 and words[-2] == 'by' else 0.43
    if word in ('itself', 'themselves', 'himself', 'herself', 'yourself'):
        if last == 'in':
            return 3.94 if word == 'itself' else 1.27
        if last == 'of':
            return 0.68
        if last == 'on':
            return 0.25
    if last == 'before' and word in ('i', 'you', 'we'):
        return 1.0
    if word == 'day' and words == ['at', 'the', 'end', 'of', 'the']:
        return 3.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, history = '', ''
    else:
        _, tail, history = carry
    token = prefix.token_strings[-1]
    value = 0.0
    feat = morphology(tail, token)
    if feat is not None:
        kind, age, length, frequency, root_frequency, lexicalized = feat
        cutoff, decay, single, lexical, intercept, slope = PARAMS[kind]
        strength = max(0.0, cutoff-frequency) / (1+decay*age)
        if length == 1:
            strength *= single
        if lexicalized:
            strength *= lexical
        value = -strength * max(0.0, intercept+slope*root_frequency)
    value += qualification(history, token)
    m = TAIL.search(tail + token)
    tail = m[0][-48:] if m else ''
    history = (history + token)[-96:]
    return (doc, tail, history), float(value)

programs.haiku:
"""Negation prefixes split off a word ("un", "non", "und", ...).

Component layers.1.mlp.down_proj:4987 is mostly a negative-going detector for the
piece of a word that follows a word-initial negative prefix, such as " un" in
" un" + "enc" + "ased", " und" + "ist" + "urbed", or " non" + "-" + "numeric".
The activation is strongest for "un-" (about -2.4), weaker for "non-" (about -1.2),
and weakest for a one-letter continuation. The same prefix mid-word (as in
"university") does nothing.

Secondary, positive: a standalone negation ("not", "no", "n't") followed by
an idiom word such as "by no MEANS", "not EXACTLY", "doesn't MEAN", "not SURE"
gives about +1.5. Everything else predicts 0.
"""

READS = ()

UN_PREFIXES = {"un", "_un", "_uns", "und", "unf", "unc", "unt", "unb", "unm", "unw", "unp", "ung", "uns"}
NON_PREFIXES = {"non", "nond"}
NEGATORS = {"not", "no", "n't", "’t", "'t", "never"}
IDIOM_WORDS = {"mean", "means", "exactly", "say", "saying", "sure", "that", "so", "very", "much"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    t = prefix.position
    # Only look back within the same document.
    if t < 2 or docs[t - 1] != docs[t] or docs[t - 2] != docs[t]:
        return None, 0.0
    prev, cur = toks[t - 1], toks[t]

    # Positive: a free-standing negation followed by an idiom word.
    if cur.startswith(" "):
        if prev.strip().lower() in NEGATORS and cur.strip().lower() in IDIOM_WORDS:
            return None, 1.5
        return None, 0.0

    # Hyphenated: non-numeric, un-hashable written as "non" "-" "numeric".
    if prev == "-":
        if toks[t - 2].strip().lower() in NON_PREFIXES | UN_PREFIXES:
            return None, -1.7
        return None, 0.0

    # The current token continues a word, and the previous token is a
    # word-initial negative prefix (not the middle of a longer word).
    word_start = prev.startswith(" ") or prev.startswith("_") or not toks[t - 2][-1:].isalnum()
    if word_start:
        key = prev.strip().lower()
        if key in UN_PREFIXES:
            return None, (-0.5 if len(cur) == 1 else -2.4)
        if key in NON_PREFIXES:
            return None, -1.2
    return None, 0.0

programs.sol:
"""Approximate a negative response to adjective-making -able/-ible morphology.

Track the unfinished word across tokens. Recognizable suffix fragments fire,
especially on evaluative words, Italian -evole, and words more common in a
Romance language or German than English. Complete evaluative words also fire.
Doubled-L endings have a weak positive response. This captures morphology,
not all of the component's word-specific variation. Reset at each document.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
EVALUATIVE = set('''reasonable acceptable favorable favourable considerable
remarkable notable memorable preferable admirable inevitable probable'''.split())
OTHER_EVALUATIVE = set('''desirable allowable sensible horrible terrible formidable
unforgettable recognizable understandable noticeable questionable invaluable
respectable avoidable'''.split())
EVIDENTIAL = set('''necessarily presumably evidently undoubtedly inevitably
notably notamment reportedly potentially'''.split())
# Related stems for rationality, esteem, favorability and responsibility.
JUDGMENT_ROOTS = (
    'reason', 'raisonn', 'favor', 'favour', 'honor', 'honour', 'consider',
    'prefer', 'remark', 'remarqu', 'confort', 'responsab',
)
FOREIGN_LANGUAGES = ('fr', 'es', 'it', 'pt', 'ro', 'de')


def unaccent(word):
    return ''.join(c for c in unicodedata.normalize('NFD', word)
                   if not unicodedata.combining(c))


def has_ending(word, pattern):
    return re.fullmatch(r'.{2,}(?:' + pattern + ')', word) is not None


@lru_cache(maxsize=4096)
def unfinished_adjective(word):
    """Check that completing the fragment produces a more familiar word."""
    endings = ('le', 'ile', 'ili') if word.endswith(('ab', 'ib')) else ('ole', 'oli')
    for lang in ('en', 'fr', 'es', 'it', 'pt', 'de'):
        threshold = max(2.5, zipf_frequency(word, lang) + 1)
        if any(zipf_frequency(word + end, lang) > threshold for end in endings):
            return True
    return False


def foreign_word(word, plain, languages=FOREIGN_LANGUAGES):
    return max(zipf_frequency(word, lang) for lang in languages) > max(
        2.0, zipf_frequency(plain, 'en') + 0.5)


@lru_cache(maxsize=16384)
def response(before, token):
    match = re.search(r'[^\W\d_]+$', before + token)
    word = match[0].lower()[-80:] if match else ''
    plain = unaccent(word)
    value = None
    if not before and token in ('able', 'ables', 'ible', 'ibles', 'ably', 'ibly'):
        return word, -1.6
    if before and token.isalpha():
        # A completed suffix should not fire again on an added plural S.
        if not re.search(r'(?:able|ible|ably|ibly|ables|ibles)$', before):
            if has_ending(plain, 'ab|ib|ev'):
                if plain in ('reasonab', 'unreasonab'):
                    return word, -9.9
                if unfinished_adjective(plain):
                    value = -1.9
            if value is None:
                if has_ending(plain, 'evol[ei]?'):
                    return word, -6.8
                if has_ending(plain, 'ably|ibly'):
                    value = -1.5
                elif has_ending(plain, 'ables?|ibles?|abel|ibel'):
                    if plain in ('honorable', 'honourable'):
                        return word, -7.6
                    value = -0.6
                elif has_ending(plain,
                                '(?:abil|ibil)(?:i|e|a|it|ity|ities|idad|idade|ita)?'):
                    value = -0.7
                elif has_ending(plain, 'aveis|iveis|avel|ivel'):
                    value = -0.2
                elif has_ending(plain,
                                '(?:ab|ib)(?:lement|lemente|leness|ilmente)|evolmente'):
                    value = -2.5
                elif has_ending(plain, '(?:abil|ebil)(?:ir|e|m|me|mek|di|iy|iyor)?'):
                    return word, -2.2
            if value is not None:
                adjective = (plain[:-1] + 'e'
                             if plain.endswith(('ably', 'ibly')) else plain)
                base = adjective[2:] if adjective.startswith('un') else adjective
                if plain.startswith(JUDGMENT_ROOTS) or base in EVALUATIVE:
                    return word, -5.1
                if base in OTHER_EVALUATIVE:
                    return word, -2.6
                return word, -2.2 if foreign_word(word, plain) else value
        if has_ending(plain, '(?:ill|ell)(?:a|e|o|as|es|os|er|ers|on|ons)?'):
            foreign = foreign_word(word, word, ('fr', 'es', 'it', 'pt'))
            return word, 0.3 if foreign else 0.1
    base = plain[2:] if plain.startswith('un') else plain
    if plain in ('honorable', 'honourable'):
        value = -7.6
    elif base in EVALUATIVE:
        value = -2.4
    elif base in OTHER_EVALUATIVE:
        value = -0.9
    elif plain == 'reasonably':
        value = -7.0
    elif plain in ('considerably', 'remarkably', 'noticeably'):
        value = -2.0
    elif plain in EVIDENTIAL:
        value = -1.1
    elif plain in ('likely', 'unlikely', 'probably', 'possibly', 'preferably'):
        value = -0.4
    elif plain in ('pleasant', 'unpleasant', 'pleasantly', 'unpleasantly'):
        value = -1.4
    elif plain in ('facile', 'facil', 'facilmente'):
        value = -1.2
    else:
        value = 0.0
    return word, value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    word, value = response(before, prefix.token_strings[-1])
    return (doc, word), value

"""A partial lexical reconstruction, with a document-start baseline.

Positive responses cover split 首 (head/first) and 巨 (giant) compounds,
丫头/丫鬟 (girl/maid), and Japanese 旦那 (husband). Seoul is especially
strong. Some government-body/title sequences give negative responses.
Traditional spellings are normalized. Document-initial tokens have a
negative baseline depending on word shape; repeated interpuncts are also
negative. Unrecognized cases return zero, not a general Chinese-word score.
"""
import regex
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')
PUBLIC_BODIES = ('委员会', '政府', '纪委', '办公室')
OFFICE_TITLES = frozenset((
    '主任', '副主任', '委员', '书记', '副书记', '秘书长',
))


def initial_value(word):
    """Coarse averages for tokens with no preceding context."""
    stripped = word.strip()
    if not stripped:
        return -0.07
    if stripped.isdigit():
        return 0.0
    if stripped.isascii() and stripped.isalpha():
        value = -0.38 if stripped[0].isupper() else -0.31
        return value + (0.15 if word.startswith(' ') else 0.0)
    return -0.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    previous = '' if new_document else carry[1]
    tail = '' if new_document else carry[2]
    word = SIMPLIFY.convert(prefix.token_strings[-1])
    value = initial_value(word) if new_document else 0.0

    if word == '··':
        value = -0.70
    elif regex.fullmatch(r'\p{Script=Han}+', word):
        if previous == '首':
            value = 4.0 if word == '尔' else 1.4
        elif previous == '巨':
            value = 0.95 if word == '乳' else 0.4
        elif previous == '丫' and word in ('头', '鬟'):
            value = 1.1
        elif previous == '旦' and word == '那':
            value = 1.2
        elif previous.endswith(PUBLIC_BODIES) and word in OFFICE_TITLES:
            value = -1.4
        elif previous.endswith('主任') and word == '委员':
            value = -1.4
        elif tail.endswith(('党中央、', '党中央，')) and word == '国务院':
            value = -1.3

    return (doc, word, (tail + word)[-16:]), value

programs.haiku:
"""Layer 1, MLP down-projection, component 4990.

Plain-terms summary: this component is almost silent. Its activation is near zero on
ordinary text, and it is large and negative on the first token of each document (the
first token of a row, or the token right after <|endoftext|>). A small set of chat and
tool markup tokens gives weaker, token-specific responses.

The program predicts:
- the first token of a row: about -0.16;
- the first token of a document inside a row (after <|endoftext|>): about -0.31;
- a few chat/tool markup tokens: their typical activation;
- everything else: 0.
"""

READS = ()

ROW_START = -0.16
DOCUMENT_START = -0.31

# Typical activation on chat-template and tool-call markup tokens.
MARKUP = {
    "<think>": 0.20,
    "</tool_call>": -0.14,
    "<tool_call>": -0.12,
    "<tool_response>": -0.06,
    "<|im_start|>": -0.07,
    "<|im_end|>": 0.05,
}


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return None, ROW_START
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, DOCUMENT_START
    return None, MARKUP.get(prefix.token_strings[-1], 0.0)

programs.sol:
"""Approximate a mixture of list/code formatting and singular-quantifier signals.

Dense backticks with nonbreaking spaces are treated as scraped code formatting.
An opening numeral one is stronger after a line break, especially a colon.
Some quantifier/one phrases contribute negatively. Small rules cover dot leaders
and document-opening punctuation. Other tokens predict zero. History is limited
to 160 characters and resets at document boundaries.
"""
import re

READS = ()


def predict(token, previous, context, first):
    word = token.strip()
    before = context.rstrip()
    if token == '\n\n' and previous == '<think>':
        return 0.157
    if len(word) >= 2 and set(word) == {'·'}:
        return 0.351
    if '`' in token and '```' not in token:
        if '\xa0' in context and context.count('`') >= 3:
            if word == '``':
                if token.startswith(' '):
                    return 1.261
                return 0.572
            if word == '`':
                return 1.11
            return 0.402
        return 0.041
    # One at the opening of a line is often a list marker.
    if token == '1':
        if first:
            return 0.376
        if context.isspace() and '\n' not in context:
            return 0.631
        if previous[-1:].isdigit():
            return -0.018
        if previous.endswith(('\n', '\\n')):
            if before.endswith('：'):
                return 1.133
            if before.endswith(':'):
                return 0.614
            if context.endswith('\n\n'):
                return 0.382
            return 0.311
        return 0.018
    # Selection and indefinite-person phrases.
    if word.lower() == 'one':
        if re.search(r'\b(each|every|any|which|either)\s*$', context, re.I):
            return -0.37
        if re.search(r'\b(no|some)\s*$', context, re.I):
            return 0.457
        return -0.055
    if word == 'of':
        if re.search(r'\b(each|every|any|which|either)\s+one$', before, re.I):
            return -1.528
        if re.search(r'\bno\s+amount$', before, re.I):
            return -1.847
    if '一' in word:
        if before.endswith(('每', '同', '哪', '某', '任', '另', '又')):
            return -0.972
        if word.startswith(('同一', '每一', '哪一', '某一', '任一', '另一')):
            return -0.972
    # Strong document-opening punctuation and spacing.
    if first:
        if token in ('\\n', '\\t'):
            return 2.274
        if word in ('|', '•'):
            return 1.588
        if token.isspace():
            return 0.266
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, context, first = '', '', True
    else:
        _, previous, context = carry
        first = False
    token = prefix.token_strings[-1]
    value = predict(token, previous, context, first)
    return (doc, token, (context + token)[-160:]), value
